1	// SPDX-License-Identifier: Apache-2.0
2	//! The OpenAI Chat Completions streaming protocol (spec § 4.2–§ 4.4, D10, D12, D20).
3	//!
4	//! Two shapes are a deviation only inside an open call of choice 0 (spec § 2.2 P-a, P-b): a chunk
5	//! without a `choices` key (`chunk_without_choices`), and a choice entry without a `delta` key
6	//! (`choice_without_delta`). A raising client drops the stream there: openai-python reads
7	//! `chunk.choices` and `choice.delta`, openai-node reads `chunk.choices`, and LangChain raises
8	//! `KeyError: 'delta'`. The decider would still hold the call. `"choices":[]` is keyed, so the
9	//! final usage chunk is conforming. The entry of choice 0 with a `finish_reason` may omit `delta`.
10	
11	use std::collections::BTreeMap;
12	
13	use bytes::Bytes;
14	use serde_json::{Map, Value, json};
15	
16	use crate::json::parse_strict;
17	use crate::openai::assembly::{self, Check, ChoiceAssembly};
18	use crate::openai::classify::{self, Chunk};
19	use crate::protocol::{Frame, Protocol, Step, StepError, Verdict, Verdicts};
20	use crate::report::notice_line;
21	use crate::sse::{self, Record};
22	use crate::types::HoldKey;
23	
24	/// The upstream fields a notice chunk copies, in upstream order. `object` is not copied: a notice
25	/// chunk always says `chat.completion.chunk`, or openai-python would skip it.
26	const META_KEYS: [&str; 4] = ["id", "created", "model", "system_fingerprint"];
27	
28	#[derive(Default)]
29	struct ChoiceState {
30	    asm: ChoiceAssembly,
31	    hold_open: bool,
32	    finished: bool,
33	    has_text: bool,
34	    notice_done: bool,
35	    /// The (position, name) of the calls handed to the decider, in hold order. Never their
36	    /// arguments: a finished choice keeps none.
37	    calls: Vec<(u32, String)>,
38	}
39	
40	pub(crate) struct OpenAiStream {
41	    choices: BTreeMap<u32, ChoiceState>,
42	    meta: Map<String, Value>,
43	    /// The most an observed choice may retain (D13, § 5.3).
44	    cap: usize,
45	}
46	
47	impl Default for OpenAiStream {
48	    fn default() -> Self {
49	        Self::with_cap(crate::limits::Limits::defaults().max_held_bytes)
50	    }
51	}
52	
53	impl OpenAiStream {
54	    pub(crate) fn with_cap(cap: usize) -> Self {
55	        OpenAiStream {
56	            choices: BTreeMap::new(),
57	            meta: Map::new(),
58	            cap,
59	        }
60	    }
61	}
62	
63	/// The scalar (string or number) `META_KEYS` fields of a record. A non-scalar value is skipped.
64	fn meta_of(v: &Value) -> Map<String, Value> {
65	    let mut m = Map::new();
66	    if let Value::Object(top) = v {
67	        for k in META_KEYS {
68	            if let Some(x @ (Value::String(_) | Value::Number(_))) = top.get(k) {
69	                m.insert(k.to_owned(), x.clone());
70	            }
71	        }
72	    }
73	    m
74	}
75	
76	fn notice_chunk(meta: &Map<String, Value>, choice: u32, text: &str) -> Bytes {
77	    let mut m = Map::new();
78	    for (k, v) in meta {
79	        m.insert(k.clone(), v.clone());
80	        if k == "id" {
81	            m.insert("object".to_owned(), classify::CHUNK_OBJECT.into());
82	        }
83	    }
84	    m.entry("object").or_insert_with(|| classify::CHUNK_OBJECT.into());
85	    m.insert("choices".to_owned(), json!([{"index": choice, "delta": {"content": text}, "finish_reason": null}]));
86	    sse::frame(None, &serde_json::to_vec(&Value::Object(m)).expect("a Value always serializes"))
87	}
88	
89	impl ChoiceState {
90	    /// The (position, name) of every call the hold knows.
91	    fn known(&self) -> Vec<(u32, String)> {
92	        if self.calls.is_empty() { self.asm.names() } else { self.calls.clone() }
93	    }
94	
95	    fn notice_text(&self, verdict: &Verdict) -> String {
96	        let lines: Vec<String> = self
97	            .known()
98	            .iter()
99	            .enumerate()
100	            .filter_map(|(slot, (_, name))| verdict.block_code(slot).map(|code| notice_line(name, code)))
101	            .collect();
102	        let body = if lines.is_empty() {
103	            notice_line("unknown", verdict.block_code(0).unwrap_or(crate::types::BlockCode::Malformed))
104	        } else {
105	            lines.join("\n")
106	        };
107	        if self.has_text { format!("\n\n{body}") } else { body }
108	    }
109	
110	    fn allowed_left(&self, verdict: &Verdict) -> usize {
111	        (0..self.known().len()).filter(|slot| verdict.block_code(*slot).is_none()).count()
112	    }
113	}
114	
115	impl Protocol for OpenAiStream {
116	    fn step(&mut self, rec: Record, verdicts: &Verdicts) -> Result<Step, StepError> {
117	        if rec.data == b"[DONE]" {
118	            return Ok(Step::End(Frame {
119	                event: None,
120	                payload: rec.data,
121	                value: None,
122	                touches: Vec::new(),
123	            }));
124	        }
125	        let value = parse_strict(&rec.data)?;
126	        let (choices, keyed) = match classify::chunk(&value)? {
127	            Chunk::UpstreamError => {
128	                return Ok(Step::UpstreamError(Frame {
129	                    event: None,
130	                    payload: rec.data,
131	                    value: Some(value),
132	                    touches: Vec::new(),
133	                }));
134	            }
135	            Chunk::Choices { choices, keyed } => (choices, keyed),
136	        };
137	        // Phase 1 checks the whole record and changes nothing. A deviation in any choice drops the
138	        // record, so no choice may have been changed by then: a hold marked open that the
139	        // interceptor never registered would wait for a verdict for ever.
140	        let empty = ChoiceAssembly::default();
141	        // Inside an open call of choice 0, a chunk without `choices` or a choice without `delta` is
142	        // dropped by a raising client: openai-python reads `chunk.choices`/`choice.delta` and raises,
143	        // openai-node reads `chunk.choices`, LangChain raises `KeyError: 'delta'`. The decider would
144	        // still see the call. The entry of choice 0 that carries `finish_reason` may omit `delta`.
145	        let open_call = self.choices.get(&0).is_some_and(|s| s.hold_open && !s.finished);
146	        if open_call && !keyed {
147	            return Err(StepError::Deviation("chunk_without_choices"));
148	        }
149	        let mut planned: Vec<Option<Check>> = Vec::with_capacity(choices.len());
150	        let mut new_choices = 0;
151	        for (position, cv) in choices.iter().enumerate() {
152	            if open_call && !cv.has_delta && !(cv.index == 0 && cv.finish_reason.is_some()) {
153	                return Err(StepError::Deviation("choice_without_delta"));
154	            }
155	            let key = HoldKey::Choice(cv.index);
156	            let st = self.choices.get(&cv.index);
157	            if st.is_none() {
158	                if cv.index as usize != self.choices.len() + new_choices {
159	                    return Err(StepError::Deviation("choice_order"));
160	                }
161	                new_choices += 1;
162	            }
163	            let (finished, hold_open, asm) = st.map_or((false, false, &empty), |s| (s.finished, s.hold_open, &s.asm));
164	            let tools = !cv.fragments.is_empty() || cv.legacy.is_some();
165	            let undecided = !verdicts.contains_key(&key);
166	            let mut after = None;
167	            if tools {
168	                assembly::check_tool_choice(cv.index, position, &cv.fragments, cv.legacy.as_ref())?;
169	                if finished {
170	                    return Err(StepError::Deviation("late_fragment"));
171	                }
172	                if undecided {
173	                    after = Some(asm.check(&cv.fragments, cv.legacy.as_ref())?);
174	                }
175	            }
176	            if cv.finish_reason.is_some() {
177	                if finished {
178	                    return Err(StepError::Deviation("second_finish"));
179	                }
180	                if (hold_open || tools) && undecided {
181	                    asm.check_finish(&cv.fragments, cv.legacy.as_ref(), after.as_ref().unwrap_or(asm.state()))?;
182	                }
183	            }
184	            planned.push(after);
185	        }
186	        // Phase 2 applies the checked record. Only an accepted record updates the notice meta.
187	        for (k, v) in meta_of(&value) {
188	            self.meta.insert(k, v);
189	        }
190	        let (mut touches, mut opened, mut completed) = (Vec::new(), Vec::new(), Vec::new());
191	        for (cv, after) in choices.into_iter().zip(planned) {
192	            let key = HoldKey::Choice(cv.index);
193	            let st = self.choices.entry(cv.index).or_default();
194	            if cv.has_text {
195	                st.has_text = true;
196	            }
197	            if !cv.fragments.is_empty() || cv.legacy.is_some() {
198	                match (verdicts.get(&key), after) {
199	                    (None, Some(after)) => st.asm.commit(&cv.fragments, cv.legacy.as_ref(), after),
200	                    (Some(Verdict::PassThrough), _) => st.asm.observe(&cv.fragments, cv.legacy.as_ref(), self.cap),
201	                    _ => {}
202	                }
203	                if !st.hold_open {
204	                    st.hold_open = true;
205	                    opened.push(key);
206	                }
207	                touches.push(key);
208	            }
209	            if cv.finish_reason.is_some() {
210	                st.finished = true;
211	                if st.hold_open {
212	                    touches.push(key);
213	                    let finished = match verdicts.get(&key) {
214	                        // Phase 1 ran the same check on the same state, so this cannot fail.
215	                        None => Some(st.asm.finish(cv.index)?),
216	                        Some(Verdict::PassThrough) if !st.asm.overflowed() => st.asm.finish(cv.index).ok(),
217	                        Some(_) => None,
218	                    };
219	                    st.asm.drop_buffers();
220	                    if let Some(calls) = finished {
221	                        st.calls = calls.iter().map(|c| (c.position, c.name.clone())).collect();
222	                        completed.push((key, calls));
223	                    }
224	                }
225	            }
226	        }
227	        touches.sort();
228	        touches.dedup();
229	        Ok(Step::Frame {
230	            frame: Frame {
231	                event: None,
232	                payload: rec.data,
233	                value: Some(value),
234	                touches,
235	            },
236	            opened,
237	            completed,
238	            reports: Vec::new(),
239	        })
240	    }
241	
242	    fn incomplete(&self) -> Vec<HoldKey> {
243	        self.choices.iter().filter(|(_, s)| s.hold_open && !s.finished).map(|(c, _)| HoldKey::Choice(*c)).collect()
244	    }
245	
246	    fn release(&mut self, frame: Frame, verdicts: &Verdicts) -> Vec<Bytes> {
247	        let Some(mut value) = frame.value else {
248	            let mut out = self.closing(verdicts);
249	            out.push(sse::frame(None, &frame.payload));
250	            return out;
251	        };
252	        let blocking: Vec<u32> = frame
253	            .touches
254	            .iter()
255	            .filter_map(|k| match (k, verdicts.get(k)) {
256	                (HoldKey::Choice(c), Some(v)) if v.blocks_any() => Some(*c),
257	                _ => None,
258	            })
259	            .collect();
260	        if blocking.is_empty() {
261	            return vec![sse::frame(None, &frame.payload)];
262	        }
263	        let meta = meta_of(&value);
264	        let mut notices = Vec::new();
265	        if let Some(Value::Array(choices)) = value.get_mut("choices") {
266	            for ch in choices.iter_mut() {
267	                let idx = ch.get("index").and_then(Value::as_u64).and_then(|i| u32::try_from(i).ok()).unwrap_or(0);
268	                if let Some(v) = verdicts.get(&HoldKey::Choice(idx)).filter(|_| blocking.contains(&idx)) {
269	                    let st = self.choices.entry(idx).or_default();
270	                    if let Some(text) = rewrite_choice(ch, v, st) {
271	                        notices.push(notice_chunk(&meta, idx, &text));
272	                    }
273	                }
274	            }
275	        }
276	        // P-10: never drop the frame or a choice entry. openai-python finds a choice by list
277	        // position, so a missing first appearance would shift every later choice.
278	        notices.push(sse::frame(None, &serde_json::to_vec(&value).expect("a Value always serializes")));
279	        notices
280	    }
281	
282	    fn closing(&mut self, verdicts: &Verdicts) -> Vec<Bytes> {
283	        let mut out = Vec::new();
284	        for (idx, st) in &mut self.choices {
285	            let Some(v) = verdicts.get(&HoldKey::Choice(*idx)) else { continue };
286	            if st.hold_open && v.blocks_any() && !st.notice_done {
287	                st.notice_done = true;
288	                out.push(notice_chunk(&self.meta, *idx, &st.notice_text(v)));
289	            }
290	        }
291	        out
292	    }
293	
294	    fn known_calls(&self, hold: HoldKey) -> Vec<(u32, String)> {
295	        match hold {
296	            HoldKey::Choice(c) => self.choices.get(&c).map(ChoiceState::known).unwrap_or_default(),
297	            HoldKey::Block(_) => Vec::new(),
298	        }
299	    }
300	
301	    fn unframed(&self, rec: Record) -> Bytes {
302	        sse::frame(None, &rec.data)
303	    }
304	
305	    #[cfg(test)]
306	    fn retained(&self) -> usize {
307	        self.choices.values().map(|s| s.asm.retained()).sum()
308	    }
309	}
310	
311	/// Rewrite one choice entry in place (§ 4.4). Returns the notice text when this entry carries the
312	/// choice's `finish_reason` and the notice is still owed.
313	fn rewrite_choice(ch: &mut Value, verdict: &Verdict, st: &mut ChoiceState) -> Option<String> {
314	    let slots: Vec<u32> = st.known().iter().map(|(p, _)| *p).collect();
315	    let slot_of = |pos: u32| slots.iter().position(|p| *p == pos).unwrap_or(slots.len());
316	    let rank = |pos: u32| -> u32 { u32::try_from((0..slot_of(pos)).filter(|s| verdict.block_code(*s).is_none()).count()).expect("at most 128 calls per choice") };
317	    if let Some(Value::Object(delta)) = ch.get_mut("delta") {
318	        if let Some(Value::Array(tc)) = delta.get_mut("tool_calls") {
319	            tc.retain_mut(|e| {
320	                let pos = e.get("index").and_then(Value::as_u64).and_then(|i| u32::try_from(i).ok()).unwrap_or(0);
321	                if verdict.block_code(slot_of(pos)).is_some() {
322	                    return false;
323	                }
324	                e["index"] = rank(pos).into();
325	                true
326	            });
327	            if tc.is_empty() {
328	                delta.remove("tool_calls");
329	            }
330	        }
331	        if delta.contains_key("function_call") && verdict.block_code(0).is_some() {
332	            delta.remove("function_call");
333	        }
334	    }
335	    if let Value::Object(o) = ch {
336	        o.remove("logprobs");
337	    }
338	    let finish = ch.get("finish_reason").and_then(Value::as_str).map(str::to_owned)?;
339	    if st.allowed_left(verdict) == 0 && (finish == "tool_calls" || finish == "function_call") {
340	        ch["finish_reason"] = "stop".into();
341	    }
342	    if st.notice_done {
343	        return None;
344	    }
345	    st.notice_done = true;
346	    Some(st.notice_text(verdict))
347	}
