349	#[cfg(test)]
350	mod tests {
351	    use super::*;
352	    use crate::protocol::{Protocol, Step, Verdict, Verdicts};
353	    use crate::sse::Record;
354	    use crate::types::{BlockCode, Decision, HoldKey};
355	    use serde_json::{Value, json};
356	
357	    fn rec(s: &str) -> Record {
358	        Record {
359	            event: None,
360	            data: s.as_bytes().to_vec(),
361	        }
362	    }
363	    fn chunk(choices: Value) -> String {
364	        json!({"id":"chatcmpl-1","object":"chat.completion.chunk","created":1,"model":"m","system_fingerprint":"fp","choices":choices}).to_string()
365	    }
366	
367	    /// Steps every record, then releases every frame under `verdict` for each completed hold.
368	    /// Returns the concatenated output and the completed calls.
369	    fn run(records: &[String], verdict: impl Fn(&[crate::types::ToolCall]) -> Verdict) -> (String, Vec<crate::types::ToolCall>) {
370	        let mut p = OpenAiStream::default();
371	        let mut verdicts = Verdicts::new();
372	        let mut frames = Vec::new();
373	        let mut calls = Vec::new();
374	        for r in records {
375	            match p.step(rec(r), &verdicts).ok().expect("canonical record") {
376	                Step::Frame { frame, completed, .. } => {
377	                    for (k, c) in completed {
378	                        verdicts.insert(k, verdict(&c));
379	                        calls.extend(c);
380	                    }
381	                    frames.push(frame);
382	                }
383	                Step::End(f) | Step::UpstreamError(f) => frames.push(f),
384	            }
385	        }
386	        let mut out = Vec::new();
387	        for f in frames {
388	            for b in p.release(f, &verdicts) {
389	                out.extend_from_slice(&b);
390	            }
391	        }
392	        for b in p.closing(&verdicts) {
393	            out.extend_from_slice(&b);
394	        }
395	        (String::from_utf8(out).unwrap(), calls)
396	    }
397	
398	    fn two_calls() -> Vec<String> {
399	        vec![
400	            chunk(json!([{"index":0,"delta":{"role":"assistant","content":"Sure."},"finish_reason":null}])),
401	            chunk(json!([{"index":0,"delta":{"tool_calls":[{"index":0,"id":"c0","type":"function","function":{"name":"read","arguments":"{}"}}]},"finish_reason":null}])),
402	            chunk(
403	                json!([{"index":0,"delta":{"tool_calls":[{"index":1,"id":"c1","type":"function","function":{"name":"rm","arguments":"{\"p\":\"/\"}"}}]},"logprobs":{"content":[{"token":"rm"}]},"finish_reason":null}]),
404	            ),
405	            chunk(json!([{"index":0,"delta":{},"finish_reason":"tool_calls"}])),
406	            "[DONE]".to_owned(),
407	        ]
408	    }
409	
410	    #[test]
411	    fn allow_all_reemits_every_payload_unchanged() {
412	        let records = two_calls();
413	        let (out, calls) = run(&records, |c| Verdict::PerCall(vec![Decision::Allow; c.len()]));
414	        let want: String = records.iter().map(|r| format!("data: {r}\n\n")).collect();
415	        assert_eq!(out, want);
416	        assert_eq!(calls.iter().map(|c| c.name.as_str()).collect::<Vec<_>>(), ["read", "rm"]);
417	    }
418	
419	    #[test]
420	    fn a_blocked_second_call_is_removed_and_its_logprobs_stripped() {
421	        let (out, _) = run(&two_calls(), |_| Verdict::PerCall(vec![Decision::Allow, Decision::Block { code: BlockCode::Policy }]));
422	        assert!(!out.contains("\\\"p\\\""), "the blocked arguments leaked: {out}");
423	        assert!(!out.contains("\"token\":\"rm\""), "the logprobs leaked: {out}");
424	        assert!(out.contains("\"name\":\"read\""));
425	        assert!(out.contains(r#"[paigasus] tool call \"rm\" was blocked (policy)."#));
426	        assert!(out.contains("\"finish_reason\":\"tool_calls\""), "one call remains, so finish_reason stays");
427	        let notice_at = out.find("[paigasus]").unwrap();
428	        let finish_at = out.find("\"finish_reason\":\"tool_calls\"").unwrap();
429	        assert!(notice_at < finish_at, "the notice precedes the finish frame");
430	        assert!(out.ends_with("data: [DONE]\n\n"));
431	    }
432	
433	    #[test]
434	    fn blocking_every_call_rewrites_finish_reason_to_stop_and_keeps_role() {
435	        let records = vec![
436	            chunk(
437	                json!([{"index":0,"delta":{"role":"assistant","content":null,"tool_calls":[{"index":0,"id":"c0","type":"function","function":{"name":"rm","arguments":"\"x\""}}]},"finish_reason":null}]),
438	            ),
439	            chunk(json!([{"index":0,"delta":{},"finish_reason":"tool_calls"}])),
440	        ];
441	        let (out, _) = run(&records, |_| Verdict::BlockAll(BlockCode::Policy));
442	        assert!(out.contains("\"role\":\"assistant\""), "role is kept: {out}");
443	        assert!(!out.contains("tool_calls\":["), "no tool_calls remain: {out}");
444	        assert!(out.contains("\"finish_reason\":\"stop\""));
445	        let notice: Value = serde_json::from_str(out.lines().find(|l| l.contains("[paigasus]")).unwrap().strip_prefix("data: ").unwrap()).unwrap();
446	        assert_eq!(notice["id"], "chatcmpl-1");
447	        assert_eq!(notice["system_fingerprint"], "fp");
448	        assert_eq!(notice["choices"][0]["index"], 0);
449	        assert!(!notice["choices"][0]["delta"]["content"].as_str().unwrap().starts_with('\n'), "no text streamed before, so no prefix");
450	    }
451	
452	    #[test]
453	    fn a_legacy_call_is_blocked_and_finish_reason_function_call_becomes_stop() {
454	        let records = vec![
455	            chunk(json!([{"index":0,"delta":{"role":"assistant","content":"x","function_call":{"name":"f","arguments":"\"SECRET\""}},"finish_reason":null}])),
456	            chunk(json!([{"index":0,"delta":{},"finish_reason":"function_call"}])),
457	        ];
458	        let (out, _) = run(&records, |_| Verdict::BlockAll(BlockCode::Policy));
459	        assert!(!out.contains("SECRET"));
460	        assert!(out.contains("\"finish_reason\":\"stop\""));
461	        assert!(out.contains("\\n\\n[paigasus]"), "text streamed first, so the notice is prefixed");
462	    }
463	
464	    #[test]
465	    fn closing_owes_a_notice_for_a_truncated_blocked_choice() {
466	        let records = [chunk(
467	            json!([{"index":0,"delta":{"tool_calls":[{"index":0,"id":"c0","type":"function","function":{"name":"rm","arguments":"SEC"}}]}}]),
468	        )];
469	        let mut p = OpenAiStream::default();
470	        let Step::Frame { frame, opened, .. } = p.step(rec(&records[0]), &Verdicts::new()).ok().unwrap() else {
471	            panic!()
472	        };
473	        assert_eq!(opened, vec![HoldKey::Choice(0)]);
474	        assert_eq!(p.incomplete(), vec![HoldKey::Choice(0)]);
475	        let mut verdicts = Verdicts::new();
476	        verdicts.insert(HoldKey::Choice(0), Verdict::BlockAll(BlockCode::Truncated));
477	        let out = String::from_utf8(p.release(frame, &verdicts).concat()).unwrap();
478	        assert!(!out.contains("SEC") && !out.contains("tool_calls"), "the blocked call is gone: {out}");
479	        assert!(out.contains("\"delta\":{}"), "the choice entry is kept, emptied (P-10): {out}");
480	        let closing = String::from_utf8(p.closing(&verdicts).concat()).unwrap();
481	        assert!(closing.contains("(truncated)"));
482	        assert!(p.closing(&verdicts).is_empty(), "the notice is owed once");
483	    }
484	
485	    /// The closing notice takes its metadata only from accepted records, and only scalars: a
486	    /// dropped deviating record or a non-scalar field cannot reach the client through it.
487	    #[test]
488	    fn the_closing_notice_meta_comes_only_from_accepted_scalars() {
489	        let first = chunk(json!([{"index":0,"delta":{"tool_calls":[{"index":0,"id":"c0","type":"function","function":{"name":"rm","arguments":"{}"}}]}}]));
490	        let mut deviating: Value = serde_json::from_str(&chunk(json!([{"index":0,"delta":{"tool_calls":[{"index":0,"function":{"name":"again"}}]}}]))).unwrap();
