1	// SPDX-License-Identifier: Apache-2.0
2	//! OpenAI stream-chunk classification by a positive allowlist (spec § 4.2, D6).
3	//!
4	//! A chunk is tool-free only when it matches the strict tool-free shape. A non-empty
5	//! `tool_calls` or a `function_call` object makes it tool-bearing. Anything else is malformed.
6	//! "Has a `tool_calls` key" would be wrong both ways: it misses `tool_calls` as an object, and it
7	//! holds every text delta of an upstream that sends `"tool_calls": []`.
8	//!
9	//! A chunk that carries tool data or a `finish_reason` must say `"object":"chat.completion.chunk"`
10	//! (a body: `"chat.completion"`). openai-python's `ChatCompletionStream` skips every chunk whose
11	//! `object` differs (it filters Azure's async content-filter chunks), so a fragment in such a chunk
12	//! would reach the decider but not that client. Text-only chunks are not checked: skipping them
13	//! changes no tool call.
14	//!
15	//! Two more keys make LangChain read a chunk differently (spec § 2.2 H1, H2). A top-level `chunk`
16	//! key is malformed: LangChain reads `chunk.choices` when `choices` is empty
17	//! (`_convert_chunk_to_generation_chunk`). A top-level `"type":"content.delta"` on a chunk that
18	//! carries tool data or a `finish_reason` is malformed: LangChain skips that record.
19	
20	use serde_json::{Map, Value};
21	
22	use crate::json::{MAX_OPENAI_INDEX, Malformed, index_of, opt_obj, opt_str};
23	
24	pub(crate) enum Chunk {
25	    /// `keyed` is whether the chunk has a `choices` key at all (`"choices":[]` is keyed).
26	    Choices {
27	        choices: Vec<ChoiceView>,
28	        keyed: bool,
29	    },
30	    UpstreamError,
31	}
32	
33	pub(crate) struct ChoiceView {
34	    pub index: u32,
35	    pub fragments: Vec<Fragment>,
36	    pub legacy: Option<NameArgs>,
37	    pub finish_reason: Option<String>,
38	    pub has_text: bool,
39	    /// Whether the entry has a `delta` key.
40	    pub has_delta: bool,
41	}
42	
43	pub(crate) struct Fragment {
44	    pub index: u32,
45	    pub id: Option<String>,
46	    pub ty: Option<String>,
47	    /// Whether the entry has a `type` key. `null` counts: a client reads the key, not its value.
48	    pub ty_key: bool,
49	    pub function: Option<NameArgs>,
50	    pub custom: Option<NameArgs>,
51	    /// The whole entry, for kind Other (§ 4.1).
52	    pub raw: Value,
53	}
54	
55	pub(crate) struct NameArgs {
56	    pub name: Option<String>,
57	    pub args: Option<String>,
58	}
59	
60	/// The `object` a chunk needs once it carries tool data or a `finish_reason`, and a body once it
61	/// carries tool calls (spec § 11): openai-python skips a chunk with any other `object`.
62	pub(crate) const CHUNK_OBJECT: &str = "chat.completion.chunk";
63	pub(crate) const BODY_OBJECT: &str = "chat.completion";
64	
65	/// openai-python skips a chunk whose `object` is not `expected`. When `carries` (tool data or a
66	/// `finish_reason`), such a chunk is malformed; otherwise it is not checked.
67	pub(crate) fn check_object(top: &Map<String, Value>, expected: &str, carries: bool) -> Result<(), Malformed> {
68	    if carries && top.get("object").and_then(Value::as_str) != Some(expected) {
69	        return Err(Malformed("object"));
70	    }
71	    Ok(())
72	}
73	
74	pub(crate) fn chunk(v: &Value) -> Result<Chunk, Malformed> {
75	    let Value::Object(top) = v else { return Err(Malformed("not_object")) };
76	    if top.contains_key("error") {
77	        return if top.contains_key("choices") {
78	            Err(Malformed("error_and_choices"))
79	        } else {
80	            Ok(Chunk::UpstreamError)
81	        };
82	    }
83	    // H1 (spec § 2.2): LangChain reads `chunk.choices` when `choices` is empty.
84	    if top.contains_key("chunk") {
85	        return Err(Malformed("chunk_key"));
86	    }
87	    let keyed = top.contains_key("choices");
88	    let choices = match top.get("choices") {
89	        None => Vec::new(),
90	        Some(Value::Array(a)) => {
91	            let v: Vec<ChoiceView> = a.iter().map(choice).collect::<Result<_, _>>()?;
92	            // LangChain takes choices[0] of every chunk, so a repeated index could be merged by it.
93	            if v.iter().enumerate().any(|(i, x)| v[..i].iter().any(|y| y.index == x.index)) {
94	                return Err(Malformed("duplicate_choice_index"));
95	            }
96	            v
97	        }
98	        Some(_) => return Err(Malformed("choices")),
99	    };
100	    let carries = choices.iter().any(|c| !c.fragments.is_empty() || c.legacy.is_some() || c.finish_reason.is_some());
101	    // H2 (spec § 2.2): LangChain skips a record whose top-level `type` is `content.delta`.
102	    if carries && top.get("type").and_then(Value::as_str) == Some("content.delta") {
103	        return Err(Malformed("content_delta_type"));
104	    }
105	    check_object(top, CHUNK_OBJECT, carries)?;
106	    Ok(Chunk::Choices { choices, keyed })
107	}
108	
109	fn choice(v: &Value) -> Result<ChoiceView, Malformed> {
110	    let Value::Object(c) = v else { return Err(Malformed("choice")) };
111	    if c.contains_key("message") {
112	        return Err(Malformed("message_in_chunk"));
113	    }
114	    let index = index_of(c.get("index"), MAX_OPENAI_INDEX)?;
115	    let finish_reason = opt_str(c.get("finish_reason"), "finish_reason")?;
116	    let (fragments, legacy, has_text) = match c.get("delta") {
117	        None => (Vec::new(), None, false),
118	        Some(Value::Object(d)) => delta(d)?,
119	        Some(_) => return Err(Malformed("delta")),
120	    };
121	    Ok(ChoiceView {
122	        index,
123	        fragments,
124	        legacy,
125	        finish_reason,
126	        has_text,
127	        has_delta: c.contains_key("delta"),
128	    })
129	}
130	
131	fn delta(d: &Map<String, Value>) -> Result<(Vec<Fragment>, Option<NameArgs>, bool), Malformed> {
132	    let fragments = match d.get("tool_calls") {
133	        None | Some(Value::Null) => Vec::new(),
134	        Some(Value::Array(a)) => a.iter().map(fragment).collect::<Result<_, _>>()?,
135	        Some(_) => return Err(Malformed("tool_calls")),
136	    };
137	    let legacy = opt_obj(d.get("function_call"), "function_call")?.map(|f| name_args(f, "arguments")).transpose()?;
138	    let has_text = match d.get("content") {
139	        None | Some(Value::Null) => false,
140	        Some(Value::String(s)) => !s.is_empty(),
141	        Some(_) => return Err(Malformed("content")),
142	    };
143	    Ok((fragments, legacy, has_text))
144	}
145	
146	fn fragment(v: &Value) -> Result<Fragment, Malformed> {
147	    let Value::Object(e) = v else { return Err(Malformed("tool_call")) };
148	    let index = index_of(e.get("index"), MAX_OPENAI_INDEX)?;
149	    fragment_at(v, index)
150	}
151	
152	/// A tool-call entry at a known `index`. A non-stream body has no per-entry `index`, so its
153	/// array position stands in (spec § 4.2).
154	pub(crate) fn fragment_at(v: &Value, index: u32) -> Result<Fragment, Malformed> {
155	    let Value::Object(e) = v else { return Err(Malformed("tool_call")) };
156	    let id = opt_str(e.get("id"), "id")?;
157	    let ty = opt_str(e.get("type"), "type")?;
158	    let function = opt_obj(e.get("function"), "function")?.map(|f| name_args(f, "arguments")).transpose()?;
159	    let custom = opt_obj(e.get("custom"), "custom")?.map(|f| name_args(f, "input")).transpose()?;
160	    if function.is_some() && custom.is_some() {
161	        return Err(Malformed("function_and_custom"));
162	    }
163	    Ok(Fragment {
164	        index,
165	        id,
166	        ty,
167	        ty_key: e.contains_key("type"),
168	        function,
169	        custom,
170	        raw: v.clone(),
171	    })
172	}
173	
174	pub(crate) fn name_args(f: &Map<String, Value>, args_key: &'static str) -> Result<NameArgs, Malformed> {
175	    Ok(NameArgs {
176	        name: opt_str(f.get("name"), "name")?,
177	        args: opt_str(f.get(args_key), args_key)?,
178	    })
179	}
180	
181	#[cfg(test)]
182	mod tests {
183	    use super::*;
184	    use crate::json::parse_strict;
185	
186	    /// Classify `s`, adding `"object":"chat.completion.chunk"` when it is an object without one.
187	    fn c(s: &str) -> Result<Chunk, Malformed> {
188	        let mut v = parse_strict(s.as_bytes()).unwrap();
189	        if let Value::Object(m) = &mut v {
190	            m.entry("object").or_insert_with(|| CHUNK_OBJECT.into());
