247	        for d in [r#"{"tool_calls":[]}"#, r#"{"tool_calls":null}"#, r#"{"function_call":null}"#, r#"{}"#] {
248	            let v = choices(&format!(r#"{{"choices":[{{"index":0,"delta":{d}}}]}}"#));
249	            assert!(v[0].fragments.is_empty() && v[0].legacy.is_none(), "{d}");
