260	    fn a_tool_fragment_is_read() {
261	        let v = choices(r#"{"choices":[{"index":1,"delta":{"tool_calls":[{"index":0,"id":"call_1","type":"function","function":{"name":"rm","arguments":""}}]}}]}"#);
262	        let f = &v[0].fragments[0];
263	        assert_eq!((v[0].index, f.index, f.id.as_deref(), f.ty.as_deref()), (1, 0, Some("call_1"), Some("function")));
264	        assert_eq!(f.function.as_ref().unwrap().name.as_deref(), Some("rm"));
265	    }
