281	        for bad in [
282	            r#"[]"#,
283	            r#"{"choices":null}"#,
284	            r#"{"choices":{"0":{}}}"#,
285	            r#"{"choices":[1]}"#,
286	            r#"{"choices":[{"delta":{}}]}"#,
287	            r#"{"choices":[{"index":0.0,"delta":{}}]}"#,
288	            r#"{"choices":[{"index":0,"message":{"tool_calls":[]}}]}"#,
289	            r#"{"choices":[{"index":0,"delta":"x"}]}"#,
290	            r#"{"choices":[{"index":0,"delta":{"tool_calls":{"0":{}}}}]}"#,
291	            r#"{"choices":[{"index":0,"delta":{"tool_calls":"x"}}]}"#,
292	            r#"{"choices":[{"index":0,"delta":{"tool_calls":[1]}}]}"#,
293	            r#"{"choices":[{"index":0,"delta":{"tool_calls":[{"index":true}]}}]}"#,
294	            r#"{"choices":[{"index":0,"delta":{"tool_calls":[{"index":0,"function":{"arguments":{}}}]}}]}"#,
295	            r#"{"choices":[{"index":0,"delta":{"tool_calls":[{"index":0,"function":{},"custom":{}}]}}]}"#,
296	            r#"{"choices":[{"index":0,"delta":{"function_call":"rm"}}]}"#,
297	            r#"{"choices":[{"index":0,"delta":{"content":["x"]}}]}"#,
298	            r#"{"choices":[{"index":0,"finish_reason":1}]}"#,
299	        ] {
300	            assert!(c(bad).is_err(), "{bad}");
301	        }
302	    }
303	
304	    #[test]
305	    fn a_repeated_choice_index_in_one_chunk_is_malformed() {
306	        assert!(c(r#"{"choices":[{"index":0,"delta":{}},{"index":0,"delta":{}}]}"#).is_err());
307	        assert_eq!(choices(r#"{"choices":[{"index":0,"delta":{}},{"index":1,"delta":{"content":"t"}}]}"#).len(), 2);
308	    }
309	
310	    #[test]
311	    fn tool_data_or_a_finish_needs_the_chunk_object() {
312	        let frag = r#""delta":{"tool_calls":[{"index":0,"id":"c","type":"function","function":{"name":"x","arguments":""}}]}"#;
313	        for bad in [
314	            format!(r#"{{"choices":[{{"index":0,{frag}}}]}}"#),
315	            format!(r#"{{"object":"","choices":[{{"index":0,{frag}}}]}}"#),
316	            format!(r#"{{"object":"chat.completion","choices":[{{"index":0,{frag}}}]}}"#),
317	            r#"{"choices":[{"index":0,"delta":{"function_call":{"name":"f"}}}]}"#.to_owned(),
318	            r#"{"choices":[{"index":0,"delta":{},"finish_reason":"stop"}]}"#.to_owned(),
319	        ] {
320	            assert_eq!(raw(&bad).err(), Some(Malformed("object")), "{bad}");
321	        }
322	        assert!(raw(&format!(r#"{{"object":"chat.completion.chunk","choices":[{{"index":0,{frag}}}]}}"#)).is_ok());
323	        // Text-only and empty chunks are not checked: skipping them changes no tool call.
324	        for ok in [
325	            r#"{"choices":[{"index":0,"delta":{"content":"hi"},"finish_reason":null}]}"#,
326	            r#"{"choices":[],"usage":{"total_tokens":1}}"#,
327	            r#"{"object":"","choices":[]}"#,
328	        ] {
329	            assert!(raw(ok).is_ok(), "{ok}");
330	        }
331	    }
332	}
