1	// SPDX-License-Identifier: Apache-2.0
2	//! Canonical tool-call assembly for one OpenAI choice (spec § 4.3, D9).
3	//!
4	//! Only choice 0 may carry tool calls, and only at array position 0 of its chunk, because LangChain
5	//! reads `choices[0]` of every chunk and ignores `choice.index`. A `type` that does not match the body's shape is a deviation, because
6	//! clients ignore `type` and run the body. Kind Other is only for a call with no body at all.
7	//!
8	//! The client SDKs disagree on everything outside this form. openai-python concatenates every
9	//! string except `index` and `type`, so a second `name` fragment turns `safe_` into `safe_rm`.
10	//! openai-node replaces the name, and LangChain merges by index value. Inside the canonical form
11	//! they all agree, so the decider sees exactly what every client will run.
12	//!
13	//! A tool-call entry with no `function` body (a custom call, or an entry with only an `index`) is
14	//! bodyless. LangChain raises at the first record that holds one (`rtc["function"].get`) and drops
15	//! that whole record. After such a record, a fragment of a call that existed before it would make
16	//! LangChain's snapshot of that call a strict prefix of the other clients' (spec § 2.1 M3). So that
17	//! fragment is a deviation (`fragment_after_bodyless_entry`), also in the bodyless record itself.
18	//! A fragment that adds nothing is a deviation too, on purpose: the rule does not read content.
19	//! Calls that start in or after the bodyless record are conforming.
20	//!
21	//! Every check runs on a small copy of the state ([`Check`]) before anything is changed, so a
22	//! deviation leaves the assembly exactly as it was.
23	//!
24	//! A function call's arguments are what clients parse, so at completion they must be one complete
25	//! JSON value ([`complete_arguments`]), as an Anthropic `tool_use` input must. LangChain
26	//! partial-parses a truncated string (`{"cmd":"ls` runs as `{"cmd":"ls"}`) and openai-node can
27	//! partial-parse it too, so the decider would see a string the client reads differently.
28	
29	use serde_json::Value;
30	
31	use crate::json::{check_numbers, parse_value_strict};
32	use crate::openai::classify::{Fragment, NameArgs};
33	use crate::protocol::{Deviation, MAX_IDENTIFIER_BYTES, raw_len};
34	use crate::types::{ToolCall, ToolCallKind};
35	
36	#[derive(Clone, Copy, PartialEq, Eq)]
37	enum Shape {
38	    Function,
39	    Custom,
40	}
41	
42	/// The class of a `type` value: all that the canonical checks read of it.
43	#[derive(Clone, Copy, PartialEq, Eq)]
44	enum TyClass {
45	    Function,
46	    Custom,
47	    Other,
48	}
49	
50	/// What the canonical checks read of one call. It is small, so a whole record can be checked
51	/// against a copy before anything is changed: a deviation must never leave half-applied state, for
52	/// example a hold marked open that the interceptor never registered.
53	#[derive(Clone, Copy, Default)]
54	struct Shadow {
55	    id: bool,
56	    ty: Option<TyClass>,
57	    shape: Option<Shape>,
58	    name: bool,
59	}
60	
61	/// The canonical-form state of one choice (spec § 4.3), without the strings.
62	#[derive(Clone, Default)]
63	pub(crate) struct Check {
64	    calls: Vec<Shadow>,
65	    /// `Some(has_name)` once a legacy `function_call` fragment arrived.
66	    legacy: Option<bool>,
67	    /// The number of calls that existed before the first record with a bodyless entry was applied.
68	    bodyless_at: Option<usize>,
69	}
70	
71	fn once(slot: &mut bool, present: bool, why: &'static str) -> Result<(), Deviation> {
72	    if present {
73	        if *slot {
74	            return Err(Deviation(why));
75	        }
76	        *slot = true;
77	    }
78	    Ok(())
79	}
80	
81	/// A tool-call id or name over `MAX_IDENTIFIER_BYTES` is a deviation (each arrives at most once).
82	fn long_check(id: Option<&str>, name: Option<&str>) -> Result<(), Deviation> {
83	    if id.is_some_and(|s| s.len() > MAX_IDENTIFIER_BYTES) || name.is_some_and(|s| s.len() > MAX_IDENTIFIER_BYTES) {
84	        return Err(Deviation("long_identifier"));
85	    }
86	    Ok(())
87	}
88	
89	impl Check {
90	    fn apply(&mut self, frags: &[Fragment], legacy: Option<&NameArgs>) -> Result<(), Deviation> {
91	        let mixes = (legacy.is_some() && (!frags.is_empty() || !self.calls.is_empty())) || (!frags.is_empty() && self.legacy.is_some());
92	        if mixes {
93	            return Err(Deviation("legacy_and_tool_calls"));
94	        }
95	        if let Some(l) = legacy {
96	            long_check(None, l.name.as_deref())?;
97	            once(self.legacy.get_or_insert(false), l.name.is_some(), "repeated_name")?;
98	        }
99	        let before = self.calls.len();
100	        if let Some(n) = self.bodyless_at {
101	            if frags.iter().any(|f| (f.index as usize) < n) {
102	                return Err(Deviation("fragment_after_bodyless_entry"));
103	            }
104	        } else if frags.iter().any(|f| f.function.is_none()) {
105	            if frags.iter().any(|f| (f.index as usize) < before) {
106	                return Err(Deviation("fragment_after_bodyless_entry"));
107	            }
108	            self.bodyless_at = Some(before);
109	        }
110	        for f in frags {
111	            let pos = f.index as usize;
112	            if pos == self.calls.len() {
113	                self.calls.push(Shadow::default());
114	            } else if pos > self.calls.len() {
115	                return Err(Deviation("index_gap"));
116	            }
117	            let b = &mut self.calls[pos];
118	            long_check(f.id.as_deref(), f.function.as_ref().or(f.custom.as_ref()).and_then(|na| na.name.as_deref()))?;
119	            once(&mut b.id, f.id.is_some(), "repeated_id")?;
120	            if f.ty_key {
121	                // The type names a bodyless Other call, so it is bounded like an id or a name.
122	                long_check(f.ty.as_deref(), None)?;
123	                if b.ty.is_some() {
124	                    return Err(Deviation("repeated_type"));
125	                }
126	                // A `null` type is a present key that names no known type, so it is Other.
127	                b.ty = Some(match f.ty.as_deref() {
128	                    Some("function") => TyClass::Function,
129	                    Some("custom") => TyClass::Custom,
130	                    _ => TyClass::Other,
131	                });
132	            }
133	            let (shape, na) = match (&f.function, &f.custom) {
134	                (Some(na), None) => (Some(Shape::Function), Some(na)),
135	                (None, Some(na)) => (Some(Shape::Custom), Some(na)),
136	                _ => (None, None),
137	            };
138	            if let Some(s) = shape {
139	                match b.shape {
140	                    None => b.shape = Some(s),
141	                    Some(prev) if prev != s => return Err(Deviation("shape_changed")),
142	                    Some(_) => {}
143	                }
144	            }
145	            if let Some(na) = na {
146	                once(&mut b.name, na.name.is_some(), "repeated_name")?;
147	            }
148	        }
149	        Ok(())
150	    }
151	
152	    /// The kind of every call once the choice finishes, or the deviation that finishing is.
153	    pub(crate) fn finish(&self) -> Result<Vec<ToolCallKind>, Deviation> {
154	        if let Some(has_name) = self.legacy {
155	            if !has_name {
156	                return Err(Deviation("missing_name"));
157	            }
158	            return Ok(vec![ToolCallKind::LegacyFunctionCall]);
159	        }
160	        self.calls
161	            .iter()
162	            .map(|b| {
163	                // Clients ignore `type` and run the body, so any type other than the one the
164	                // body's shape expects is a deviation, never kind Other (spec I1).
165	                let kind = match (b.shape, b.ty) {
166	                    (Some(Shape::Function), Some(TyClass::Function) | None) => ToolCallKind::Function,
167	                    (Some(Shape::Custom), Some(TyClass::Custom) | None) => ToolCallKind::Custom,
168	                    (Some(_), Some(_)) => return Err(Deviation("type_shape_mismatch")),
169	                    (None, Some(TyClass::Function | TyClass::Custom)) => return Err(Deviation("missing_body")),
170	                    (None, _) => ToolCallKind::Other,
171	                };
172	                if kind != ToolCallKind::Other && !b.name {
173	                    return Err(Deviation("missing_name"));
174	                }
175	                Ok(kind)
176	            })
177	            .collect()
178	    }
179	}
180	
181	#[derive(Default)]
182	struct CallBuild {
183	    id: Option<String>,
184	    ty: Option<String>,
185	    name: Option<String>,
186	    args: String,
187	    raws: Vec<Value>,
188	}
189	
190	#[derive(Default)]
191	pub(crate) struct ChoiceAssembly {
192	    calls: Vec<CallBuild>,
193	    legacy: Option<CallBuild>,
194	    check: Check,
195	    /// The bytes held in arguments and raw entries.
196	    retained: usize,
197	    /// An observed choice outgrew the cap: it keeps nothing and is never decided (§ 5.3, D13).
198	    overflowed: bool,
199	}
200	
201	/// Kind Other carries its raw entries. serde_json rounds an integer beyond u64/i64, so the decider
202	/// would read a different number than a client that keeps the exact one (I1, as for bodies).
203	fn check_raws<'a>(raws: impl IntoIterator<Item = &'a Value>) -> Result<(), Deviation> {
204	    raws.into_iter().try_for_each(check_numbers).map_err(|_| Deviation("lossy_number"))
205	}
206	
207	/// Tool data is allowed only in choice 0, and only at array position 0 of its chunk (spec § 4.3).
208	/// LangChain reads `choices[0]` of every chunk and ignores `choice.index`. So a call split across
209	/// choices 0 and 1 would be merged by it but assembled separately here (`multi_choice_tool_calls`),
210	/// and a choice-0 fragment behind another choice's entry would never reach it
211	/// (`choice_position`). Text in other choices and positions stays allowed.
212	pub(crate) fn check_tool_choice(choice: u32, position: usize, frags: &[Fragment], legacy: Option<&NameArgs>) -> Result<(), Deviation> {
213	    if frags.is_empty() && legacy.is_none() {
214	        return Ok(());
215	    }
216	    if choice != 0 {
217	        return Err(Deviation("multi_choice_tool_calls"));
218	    }
219	    if position != 0 {
220	        return Err(Deviation("choice_position"));
221	    }
222	    Ok(())
223	}
224	
225	/// The arguments the decider sees for a completed call of `kind`. A function or legacy call's
226	/// arguments must be one complete JSON value; an empty string is presented as `{}`, as an empty
227	/// Anthropic input is. A custom tool's input is free-form text and is not checked; kind Other
228	/// carries its raw entry.
229	pub(crate) fn complete_arguments(kind: ToolCallKind, args: String) -> Result<String, Deviation> {
230	    match kind {
231	        ToolCallKind::Function | ToolCallKind::LegacyFunctionCall => {
232	            if args.is_empty() {
233	                Ok("{}".to_owned())
234	            } else if parse_value_strict(args.as_bytes()).is_ok() {
235	                Ok(args)
236	            } else {
237	                Err(Deviation("incomplete_arguments"))
238	            }
239	        }
240	        _ => Ok(args),
241	    }
242	}
243	
244	impl ChoiceAssembly {
245	    /// The canonical-form state after these fragments, or the deviation they are. Changes nothing.
246	    pub(crate) fn check(&self, frags: &[Fragment], legacy: Option<&NameArgs>) -> Result<Check, Deviation> {
247	        let mut c = self.check.clone();
248	        c.apply(frags, legacy)?;
249	        Ok(c)
250	    }
251	
252	    /// The current canonical-form state.
253	    pub(crate) fn state(&self) -> &Check {
254	        &self.check
255	    }
256	
257	    /// Apply fragments that [`ChoiceAssembly::check`] accepted, with `after` its result. Cannot fail.
258	    pub(crate) fn commit(&mut self, frags: &[Fragment], legacy: Option<&NameArgs>, after: Check) {
259	        if let Some(l) = legacy {
260	            let b = self.legacy.get_or_insert_with(CallBuild::default);
261	            if let Some(n) = &l.name {
262	                b.name = Some(n.clone());
263	            }
264	            if let Some(a) = &l.args {
265	                b.args.push_str(a);
266	                self.retained += a.len();
267	            }
268	        }
269	        for f in frags {
270	            let pos = f.index as usize;
271	            while self.calls.len() <= pos {
272	                self.calls.push(CallBuild::default());
273	            }
274	            let b = &mut self.calls[pos];
275	            if let Some(id) = &f.id {
276	                b.id = Some(id.clone());
277	            }
278	            if let Some(t) = &f.ty {
279	                b.ty = Some(t.clone());
280	            }
281	            if let Some(na) = f.function.as_ref().or(f.custom.as_ref()) {
282	                if let Some(n) = &na.name {
283	                    b.name = Some(n.clone());
284	                }
285	                if let Some(a) = &na.args {
286	                    b.args.push_str(a);
287	                    self.retained += a.len();
288	                }
289	            }
290	            // Only kind Other reads its raw entries, and only a call with no body is Other. A call
291	            // whose body arrived drops them, so its arguments are not held twice.
292	            if after.calls.get(pos).is_some_and(|s| s.shape.is_none()) {
293	                self.retained += raw_len(&f.raw);
294	                b.raws.push(f.raw.clone());
295	            } else if !b.raws.is_empty() {
296	                self.retained -= std::mem::take(&mut b.raws).iter().map(raw_len).sum::<usize>();
297	            }
298	        }
299	        self.check = after;
300	    }
301	
302	    /// Observe mode (§ 5.3): apply what fits, and stop retaining once the choice holds more than
303	    /// `cap` bytes. The choice is then never decided, as a pass-through call is not.
304	    pub(crate) fn observe(&mut self, frags: &[Fragment], legacy: Option<&NameArgs>, cap: usize) {
305	        if self.overflowed {
306	            return;
307	        }
308	        let _ = self.apply(frags, legacy);
309	        if self.retained > cap {
310	            self.overflowed = true;
311	            self.drop_buffers();
312	        }
313	    }
314	
315	    pub(crate) fn overflowed(&self) -> bool {
316	        self.overflowed
317	    }
318	
319	    /// Drop every argument and raw buffer, keeping the names. Used once the choice finished.
320	    pub(crate) fn drop_buffers(&mut self) {
321	        for b in self.calls.iter_mut().chain(&mut self.legacy) {
322	            b.args = String::new();
323	            b.raws = Vec::new();
324	        }
325	        self.retained = 0;
326	    }
327	
328	    /// Check, then commit. On a deviation nothing is changed.
329	    pub(crate) fn apply(&mut self, frags: &[Fragment], legacy: Option<&NameArgs>) -> Result<(), Deviation> {
330	        let after = self.check(frags, legacy)?;
331	        self.commit(frags, legacy, after);
332	        Ok(())
333	    }
334	
335	    /// Phase-1 form of [`ChoiceAssembly::finish`]: whether finishing would succeed once `frags` and
336	    /// `legacy` (already accepted by [`ChoiceAssembly::check`], with result `after`) are applied.
337	    /// Changes nothing.
338	    pub(crate) fn check_finish(&self, frags: &[Fragment], legacy: Option<&NameArgs>, after: &Check) -> Result<(), Deviation> {
339	        let kinds = after.finish()?;
340	        let pending = |own: Option<&CallBuild>, more: &mut dyn Iterator<Item = &str>| -> String {
341	            let mut a = own.map(|b| b.args.clone()).unwrap_or_default();
342	            more.for_each(|x| a.push_str(x));
343	            a
344	        };
345	        if after.legacy.is_some() {
346	            let args = pending(self.legacy.as_ref(), &mut legacy.and_then(|l| l.args.as_deref()).into_iter());
347	            return complete_arguments(ToolCallKind::LegacyFunctionCall, args).map(drop);
348	        }
349	        for (i, kind) in kinds.into_iter().enumerate() {
350	            let mine = frags.iter().filter(|f| f.index as usize == i);
351	            if kind == ToolCallKind::Other {
352	                check_raws(self.calls.get(i).into_iter().flat_map(|b| &b.raws).chain(mine.map(|f| &f.raw)))?;
353	                continue;
354	            }
355	            let mut more = mine.filter_map(|f| f.function.as_ref().or(f.custom.as_ref()).and_then(|na| na.args.as_deref()));
356	            complete_arguments(kind, pending(self.calls.get(i), &mut more))?;
357	        }
358	        Ok(())
359	    }
360	
361	    /// The completed calls. Moves the buffers out, so a finished choice keeps no arguments.
362	    pub(crate) fn finish(&mut self, choice: u32) -> Result<Vec<ToolCall>, Deviation> {
363	        let kinds = self.check.finish()?;
364	        self.retained = 0;
365	        if let Some(b) = &mut self.legacy {
366	            return Ok(vec![ToolCall {
367	                choice,
368	                position: 0,
369	                id: None,
370	                name: b.name.clone().unwrap_or_default(),
371	                kind: ToolCallKind::LegacyFunctionCall,
372	                arguments: complete_arguments(ToolCallKind::LegacyFunctionCall, std::mem::take(&mut b.args))?,
373	            }]);
374	        }
375	        let mut out = Vec::with_capacity(self.calls.len());
376	        for ((i, b), kind) in self.calls.iter_mut().enumerate().zip(kinds) {
377	            let (name, arguments) = if kind == ToolCallKind::Other {
378	                let name = b.name.clone().or_else(|| b.ty.clone()).unwrap_or_else(|| "unknown".to_owned());
379	                let raws = std::mem::take(&mut b.raws);
380	                check_raws(&raws)?;
381	                (name, serde_json::to_string(&raws).expect("a Value array always serializes"))
382	            } else {
383	                b.raws = Vec::new();
384	                (b.name.clone().unwrap_or_default(), complete_arguments(kind, std::mem::take(&mut b.args))?)
385	            };
386	            let position = u32::try_from(i).expect("at most 128 calls per choice");
387	            out.push(ToolCall {
388	                choice,
389	                position,
390	                id: b.id.clone(),
391	                name,
392	                kind,
393	                arguments,
394	            });
395	        }
396	        Ok(out)
397	    }
398	
399	    /// The argument and raw-entry bytes held, measured exactly. Tests only.
400	    #[cfg(test)]
401	    pub(crate) fn retained(&self) -> usize {
402	        self.calls.iter().chain(&self.legacy).map(|b| b.args.len() + crate::protocol::raws_len(&b.raws)).sum()
403	    }
404	
405	    pub(crate) fn names(&self) -> Vec<(u32, String)> {
406	        let name = |b: &CallBuild| b.name.clone().unwrap_or_else(|| "unknown".to_owned());
407	        if let Some(b) = &self.legacy {
408	            return vec![(0, name(b))];
409	        }
410	        self.calls.iter().enumerate().map(|(i, b)| (u32::try_from(i).expect("at most 128 calls per choice"), name(b))).collect()
411	    }
412	}
