707	        let (f, l) = frags(r#"{"choices":[{"index":0,"delta":{"function_call":{"arguments":"x"}}}]}"#);
708	        assert_eq!(check_tool_choice(0, 2, &f, l.as_ref()).unwrap_err().0, "choice_position");
709	        // Both rules compose: a later choice at a later position is still a multi-choice call.
710	        assert_eq!(check_tool_choice(1, 1, &f, l.as_ref()).unwrap_err().0, "multi_choice_tool_calls");
711	    }
712	
713	    #[test]
714	    fn function_arguments_must_be_one_complete_json_value() {
715	        let cases: &[(&[&str], Result<&str, &str>)] = &[
716	            (&[""], Ok("{}")),
717	            (&[r#"{\"p\":"#, "1}"], Ok(r#"{"p":1}"#)),
718	            (&[r#"{\"p\":"#, "1"], Err("incomplete_arguments")),
719	            (&[r#"{\"a\":1}"#, r#"{\"b\":2}"#], Err("incomplete_arguments")),
720	            (&[r#"{\"a\":1,\"a\":2}"#], Err("incomplete_arguments")),
721	        ];
722	        for (pieces, want) in cases {
723	            let mut a = ChoiceAssembly::default();
724	            for (k, p) in pieces.iter().enumerate() {
725	                let e = if k == 0 {
726	                    format!(r#"{{"index":0,"id":"c","type":"function","function":{{"name":"x","arguments":"{p}"}}}}"#)
727	                } else {
728	                    format!(r#"{{"index":0,"function":{{"arguments":"{p}"}}}}"#)
729	                };
730	                feed(&mut a, &tc(&e)).unwrap();
731	            }
732	            let got = a.finish(0).map(|c| c[0].arguments.clone()).map_err(|d| d.0);
733	            assert_eq!(got.as_deref().map_err(|e| *e), *want, "{pieces:?}");
734	        }
735	        // The legacy call follows the same rule; a custom tool's free-form input does not.
736	        let mut a = ChoiceAssembly::default();
737	        feed(&mut a, r#"{"choices":[{"index":0,"delta":{"function_call":{"name":"f","arguments":"{"}}}]}"#).unwrap();
738	        assert_eq!(a.finish(0).unwrap_err().0, "incomplete_arguments");
739	        let mut a = ChoiceAssembly::default();
740	        feed(&mut a, r#"{"choices":[{"index":0,"delta":{"function_call":{"name":"f"}}}]}"#).unwrap();
741	        assert_eq!(a.finish(0).unwrap()[0].arguments, "{}");
742	        let mut a = ChoiceAssembly::default();
743	        feed(&mut a, &tc(r#"{"index":0,"id":"c","type":"custom","custom":{"name":"sql","input":"SELECT ("}}"#)).unwrap();
744	        assert_eq!(a.finish(0).unwrap()[0].arguments, "SELECT (");
745	    }
746	
747	    #[test]
748	    fn check_finish_agrees_with_finish() {
749	        // Phase 1 of the stream step must reject exactly what finish rejects.
750	        for (first, last) in [(r#"{\"p\":"#, "1}"), (r#"{\"p\":"#, "1"), ("", ""), ("{}", "{}")] {
751	            let mut a = ChoiceAssembly::default();
752	            feed(&mut a, &tc(&format!(r#"{{"index":0,"id":"c","type":"function","function":{{"name":"x","arguments":"{first}"}}}}"#))).unwrap();
753	            let (f, l) = frags(&tc(&format!(r#"{{"index":0,"function":{{"arguments":"{last}"}}}}"#)));
754	            let after = a.check(&f, l.as_ref()).unwrap();
755	            let phase1 = a.check_finish(&f, l.as_ref(), &after).map_err(|d| d.0);
756	            a.commit(&f, l.as_ref(), after);
757	            assert_eq!(phase1, a.finish(0).map(drop).map_err(|d| d.0), "{first:?} + {last:?}");
758	        }
759	    }
