2	//! OpenAI non-stream bodies (spec § 4.2, § 4.4).
3	//!
4	//! Each `choices[].message` is turned into the same fragments the stream classifier produces and
5	//! goes through the same assembly (`check_tool_choice`, `ChoiceAssembly`), so the decider sees
6	//! the calls a client sees and the canonical rules cannot drift between the stream and the body.
7	//! A `Deviation` there is `Malformed` here: a body has no earlier frame to release.
8	//!
9	//! A body with tool calls must say `"object":"chat.completion"`, by the rule the stream applies to
10	//! chunks (`classify::check_object`). A text-only body is not checked: it carries no call.
11	
12	use serde_json::{Map, Value, json};
13	
14	use crate::json::{MAX_OPENAI_INDEX, Malformed, index_of, opt_obj};
15	use crate::openai::assembly::{ChoiceAssembly, check_tool_choice};
16	use crate::openai::classify::{BODY_OBJECT, Fragment, NameArgs, check_object, fragment_at, name_args};
17	use crate::report::notice_line;
18	use crate::types::{BlockCode, ToolCall};
19	
20	/// Tool calls per choice are bounded as in the stream, where a fragment `index` is at most 127.
21	const MAX_CALLS: usize = MAX_OPENAI_INDEX as usize + 1;
22	
23	fn message_parts(m: &Map<String, Value>) -> Result<(Vec<Fragment>, Option<NameArgs>), Malformed> {
24	    match m.get("content") {
25	        None | Some(Value::Null | Value::String(_) | Value::Array(_)) => {}
26	        Some(_) => return Err(Malformed("content")),
27	    }
28	    let entries: &[Value] = match m.get("tool_calls") {
29	        None | Some(Value::Null) => &[],
30	        Some(Value::Array(a)) => a,
31	        Some(_) => return Err(Malformed("tool_calls")),
32	    };
33	    if entries.len() > MAX_CALLS {
34	        return Err(Malformed("too_many_calls"));
35	    }
36	    let frags = entries
37	        .iter()
38	        .enumerate()
39	        .map(|(i, e)| fragment_at(e, u32::try_from(i).expect("bounded by MAX_CALLS")))
40	        .collect::<Result<Vec<_>, _>>()?;
41	    let legacy = opt_obj(m.get("function_call"), "function_call")?.map(|f| name_args(f, "arguments")).transpose()?;
42	    Ok((frags, legacy))
43	}
44	
45	pub(crate) fn calls(v: &Value) -> Result<Vec<ToolCall>, Malformed> {
46	    let Value::Object(top) = v else { return Err(Malformed("not_object")) };
47	    let Some(Value::Array(choices)) = top.get("choices") else { return Err(Malformed("choices")) };
48	    let mut out = Vec::new();
49	    let mut seen: Vec<u32> = Vec::new();
50	    let mut carries = false;
51	    for (position, ch) in choices.iter().enumerate() {
52	        let Value::Object(c) = ch else { return Err(Malformed("choice")) };
53	        if c.contains_key("delta") {
54	            return Err(Malformed("delta_in_body"));
55	        }
56	        let index = index_of(c.get("index"), MAX_OPENAI_INDEX)?;
57	        // The stream rules: a repeated index is malformed (LangChain merges it), and a first-seen
58	        // index must equal the number of choices seen so far (openai-python finds a choice by
59	        // list position, P-10).
60	        if seen.contains(&index) {
61	            return Err(Malformed("duplicate_choice_index"));
62	        }
63	        if index as usize != seen.len() {
64	            return Err(Malformed("choice_order"));
65	        }
66	        seen.push(index);
67	        let Some(Value::Object(m)) = c.get("message") else { return Err(Malformed("message")) };
68	        let (frags, legacy) = message_parts(m)?;
69	        if frags.is_empty() && legacy.is_none() {
70	            continue;
71	        }
72	        carries = true;
73	        let dev = |d: crate::protocol::Deviation| Malformed(d.0);
74	        check_tool_choice(index, position, &frags, legacy.as_ref()).map_err(dev)?;
75	        let mut asm = ChoiceAssembly::default();
76	        asm.apply(&frags, legacy.as_ref()).map_err(dev)?;
77	        out.extend(asm.finish(index).map_err(dev)?);
78	    }
79	    check_object(top, BODY_OBJECT, carries)?;
80	    Ok(out)
81	}
82	
83	pub(crate) fn rewrite(v: &mut Value, calls: &[ToolCall], codes: &[Option<BlockCode>]) {
84	    let Some(Value::Array(choices)) = v.get_mut("choices") else { return };
85	    for ch in choices {
86	        let idx = ch.get("index").and_then(Value::as_u64).and_then(|i| u32::try_from(i).ok()).unwrap_or(0);
87	        let mine: Vec<(&ToolCall, Option<BlockCode>)> = calls.iter().zip(codes).filter(|(c, _)| c.choice == idx).map(|(c, k)| (c, *k)).collect();
88	        if mine.iter().all(|(_, k)| k.is_none()) {
89	            continue;
90	        }
91	        let notice: String = mine.iter().filter_map(|(c, k)| k.map(|k| notice_line(&c.name, k))).collect::<Vec<_>>().join("\n");
92	        let remaining = mine.iter().filter(|(_, k)| k.is_none()).count();
93	        let blocked: Vec<u32> = mine.iter().filter(|(_, k)| k.is_some()).map(|(c, _)| c.position).collect();
94	        if let Value::Object(o) = ch {
95	            o.remove("logprobs");
96	        }
97	        if let Some(Value::Object(m)) = ch.get_mut("message") {
98	            if let Some(Value::Array(tc)) = m.get_mut("tool_calls") {
99	                let mut pos = 0u32;
100	                tc.retain(|_| {
101	                    let keep = !blocked.contains(&pos);
102	                    pos += 1;
103	                    keep
104	                });
105	                if tc.is_empty() {
106	                    m.remove("tool_calls");
107	                }
108	            }
109	            if m.contains_key("function_call") && blocked.contains(&0) {
110	                m.remove("function_call");
111	            }
112	            let content = m.remove("content").unwrap_or(Value::Null);
113	            let new = match content {
114	                Value::String(s) if !s.is_empty() => Value::String(format!("{s}\n\n{notice}")),
115	                Value::Array(mut parts) => {
116	                    parts.push(json!({"type": "text", "text": notice}));
117	                    Value::Array(parts)
118	                }
119	                _ => Value::String(notice),
120	            };
121	            m.insert("content".to_owned(), new);
122	        }
123	        let finish = ch.get("finish_reason").and_then(Value::as_str).map(str::to_owned);
124	        if remaining == 0 && matches!(finish.as_deref(), Some("tool_calls" | "function_call")) {
125	            ch["finish_reason"] = "stop".into();
126	        }
127	    }
128	}
129	
130	#[cfg(test)]
131	mod tests {
132	    use super::*;
133	    use serde_json::json;
134	
135	    #[test]
136	    fn a_bodyless_call_type_over_1024_bytes_is_malformed() {
137	        let body = |ty: String| json!({"object": "chat.completion", "choices": [{"index": 0, "message": {"tool_calls": [{"id": "c", "type": ty}]}}]});
138	        assert!(calls(&body("a".repeat(1024))).is_ok());
139	        assert!(matches!(calls(&body("a".repeat(1025))), Err(Malformed("long_identifier"))));
140	    }
141	
142	    #[test]
143	    fn a_function_call_and_a_custom_call_in_one_body_parse_to_two_calls() {
144	        let tool_calls = json!([
145	            {"id": "c0", "type": "function", "function": {"name": "read", "arguments": "{}"}},
146	            {"id": "c1", "type": "custom", "custom": {"name": "note", "input": "x"}}
147	        ]);
148	        let body = json!({"object": "chat.completion", "choices": [{"index": 0, "message": {"tool_calls": tool_calls}}]});
149	        assert_eq!(calls(&body).unwrap().len(), 2);
150	    }
