281	pub fn render_openai(s: &Scenario) -> Vec<u8> {
282	    let interleave = has(s, Quirk::Interleave).is_some();
283	    let bad_args = s.quirks.iter().copied().find(|(q, _)| matches!(q, Quirk::TruncatedArgs | Quirk::ConcatenatedObjects));
284	    let mut per: Vec<Vec<Value>> = s
285	        .choices
