304	        recs = per.into_iter().flatten().collect();
305	    }
306	    if let Some(at) = has(s, Quirk::MultiChoiceChunk) {
307	        // Merge record p with the first later record of another choice, that choice first.
308	        let p = at % recs.len();
309	        if let Some(q) = (p + 1..recs.len()).find(|q| choice_of(&recs[*q]) != choice_of(&recs[p])) {
310	            let later = recs.remove(q);
311	            let mut both = later["choices"].as_array().cloned().unwrap_or_default();
312	            both.extend(recs[p]["choices"].as_array().cloned().unwrap_or_default());
