317	        let tool: Vec<usize> = (0..recs.len()).filter(|i| is_tool_bearing(&recs[*i])).collect();
318	        let i = if tool.is_empty() { at % recs.len() } else { tool[at % tool.len()] };
319	        if let Value::Object(m) = &mut recs[i] {
320	            m.remove("object");
321	        }
322	    }
323	    let mut lines: Vec<String> = recs.iter().map(|r| format!("data: {r}\n\n")).collect();
324	    let mut prefix = String::new();
325	    let mut suffix = String::new();
326	    for (q, at) in &s.quirks {
327	        let pos = at % (lines.len() + 1);
328	        let insert = |lines: &mut Vec<String>, rec: String| lines.insert(pos, format!("data: {rec}\n\n"));
329	        match q {
330	            Quirk::DuplicateDelta => insert(&mut lines, format!(r#"{{"choices":[{{"index":0,"delta":{{"tool_calls":[{}]}},"delta":{{"content":"x"}}}}]}}"#, hidden_entry(json!(0)))),
