332	            Quirk::ProtoKey => insert(&mut lines, format!(r#"{{"choices":[{{"index":0,"delta":{{"__proto__":{{"tool_calls":[{}]}}}}}}]}}"#, hidden_entry(json!(0)))),
333	            Quirk::FloatIndex => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0.0))]}}])).to_string()),
334	            Quirk::BoolIndex => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(true))]}}])).to_string()),
335	            Quirk::NegativeIndex => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(-1))]}}])).to_string()),
336	            Quirk::RepeatedName => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[{"index":0,"function":{"name":"blocked_hidden","arguments":"CANARY-rn"}}]}}])).to_string()),
337	            Quirk::IndexGap => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(9))]}}])).to_string()),
338	            Quirk::NaNRecord => insert(&mut lines, format!(r#"{{"x":NaN,"choices":[{{"index":0,"delta":{{"tool_calls":[{}]}}}}]}}"#, hidden_entry(json!(0)))),
339	            Quirk::EscapedKey => insert(
340	                &mut lines,
341	                r#"{"object":"chat.completion.chunk","choices":[{"index":0,"delta":{"tool\u005fcalls":[{"index":0,"id":"call_e","type":"function","function":{"name":"blocked_escaped","arguments":"CANARY-esc"}}]}}]}"#.to_owned(),
342	            ),
