348	                    "  data: {}\n\nData: {}\n\n",
349	                    chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0))]}}])),
350	                    chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0))]}}]))
351	                ),
352	            ),
