354	                // SMA-749 D2 strips the BOM, so a client that ignores the BOM-prefixed first line
355	                // would read it after the strip (known limitation, spec § 9). Keep it off line 0.
356	                let at = if pos == 0 && has(s, Quirk::Bom).is_some() { 1 } else { pos };
357	                if at <= lines.len() {
