228	fn split_points(bytes: &[u8]) -> Vec<usize> {
229	    if bytes.len() <= 4096 {
230	        return (0..=bytes.len()).collect();
231	    }
232	    let mut v: Vec<usize> = (0..=bytes.len()).step_by(7).collect();
233	    for (i, w) in bytes.windows(2).enumerate() {
234	        if w == b"\n\n" {
235	            v.extend([i, i + 1, i + 2]);
236	        }
237	    }
238	    v.push(bytes.len());
239	    v.sort_unstable();
240	    v.dedup();
241	    v.retain(|&i| i <= bytes.len());
242	    v
243	}
