1	// SPDX-License-Identifier: Apache-2.0
2	//! Grammar-based generators of hostile upstream streams (spec § 8.1).
3	//!
4	//! Hidden calls, the ones a correct interceptor must never let through, are named `blocked_*` and
5	//! carry `CANARY` in their arguments. Allowed calls never contain `CANARY`.
6	
7	use proptest::prelude::*;
8	use serde_json::{Value, json};
9	
10	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
11	pub enum Quirk {
12	    DuplicateDelta,
13	    CaseFoldedKey,
14	    ProtoKey,
15	    FloatIndex,
16	    BoolIndex,
17	    NegativeIndex,
18	    RepeatedName,
19	    Bom,
20	    LaxLine,
21	    UnknownFields,
22	    AfterDone,
23	    NoFinalBlank,
24	    Oversized,
25	    NaNRecord,
26	    JsonBody,
27	    EventLine,
28	    IndexGap,
29	    Comments,
30	    Interleave,
31	    EscapedKey,
32	    /// A tool-bearing chunk without `"object":"chat.completion.chunk"` (openai-python skips it).
33	    DropObject,
34	    /// Two choices' records merged into one chunk, the later choice first (LangChain reads
35	    /// `choices[0]` only).
36	    MultiChoiceChunk,
37	    /// One call of choice 0 gets `type: "web_search"` with its `function` body kept.
38	    UnknownType,
39	    /// One chunk names choice 0 twice.
40	    DuplicateChoiceIndex,
41	    /// The choices are rendered in reverse order, so choice 1 appears first (P-10).
42	    ReverseChoices,
43	    /// One function or legacy call of choice 0 loses the last character of its arguments, so they
44	    /// are not one complete JSON value (`incomplete_arguments`).
45	    TruncatedArgs,
46	    /// One function or legacy call of choice 0 gets two JSON objects as arguments (`{..}{"b":2}`).
47	    ConcatenatedObjects,
48	    /// Every call's arguments gain PascalCase, `constructor` and `prototype` keys. They are
49	    /// application data, so the stream is conforming (I-1).
50	    CapitalisedArgKeys,
51	    /// A chunk without a `choices` key (`chunk_without_choices` inside an open call).
52	    NoChoicesKey,
53	    /// A chunk whose choice 0 entry has no `delta` (`choice_without_delta` inside an open call).
54	    NoDelta,
55	    /// A fragment with `"type":null` and a function body for call 0: a present `type` key counts
56	    /// as the type fragment, so it is a repeated type or a type/shape mismatch. The body keeps the
57	    /// entry a named call; a bare `{"index":0,"type":null}` is covered by the unit tests and fixture.
58	    NullType,
59	    /// A top-level `chunk` key with an empty `choices` (spec § 2.2 H1): LangChain reads
60	    /// `chunk.choices` then, so the hidden call sits inside `chunk`.
61	    ChunkKey,
62	    /// A fragment in a record with top-level `"type":"content.delta"` (spec § 2.2 H2): LangChain
63	    /// skips that record.
64	    ContentDeltaType,
65	}
66	
67	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
68	pub enum CallKind {
69	    Function,
70	    Custom,
71	    Legacy,
72	}
73	
74	#[derive(Debug, Clone)]
75	pub struct Call {
76	    pub name: &'static str,
77	    pub args: String,
78	    pub kind: CallKind,
79	    pub pieces: usize,
80	}
81	
82	#[derive(Debug, Clone)]
83	pub struct Choice {
84	    pub before: Option<String>,
85	    pub calls: Vec<Call>,
86	    pub after: Option<String>,
87	}
88	
89	#[derive(Debug, Clone)]
90	pub struct Scenario {
91	    pub choices: Vec<Choice>,
92	    pub quirks: Vec<(Quirk, usize)>,
93	    pub cuts: Vec<usize>,
94	}
95	
96	const ALLOWED: [&str; 2] = ["read_file", "send_mail"];
97	const BLOCKED: [&str; 2] = ["blocked_rm", "blocked_exfil"];
98	
99	fn call_strategy() -> impl Strategy<Value = Call> {
100	    (prop::bool::ANY, 0usize..2, "[a-z]{0,12}", 1usize..4, 0u8..10).prop_map(|(blocked, n, s, pieces, k)| {
101	        let name = if blocked { BLOCKED[n] } else { ALLOWED[n] };
102	        let args = if blocked { format!("{{\"v\":\"CANARY-{s}\"}}") } else { format!("{{\"v\":\"{s}\"}}") };
103	        let kind = match k {
104	            0 => CallKind::Custom,
105	            1 | 2 => CallKind::Legacy,
106	            _ => CallKind::Function,
107	        };
108	        Call { name, args, kind, pieces }
109	    })
110	}
111	
112	fn choice_strategy() -> impl Strategy<Value = Choice> {
113	    (prop::option::of("[a-zA-Z ]{1,10}"), prop::collection::vec(call_strategy(), 0..4), prop::option::of("[a-z ]{1,8}")).prop_map(|(before, mut calls, after)| {
114	        if calls.len() > 1 {
115	            for c in &mut calls {
116	                if c.kind == CallKind::Legacy {
117	                    c.kind = CallKind::Function; // a legacy call is the only call of its choice
118	                }
119	            }
120	        }
121	        Choice { before, calls, after }
122	    })
123	}
124	
125	fn quirk_strategy() -> impl Strategy<Value = Quirk> {
126	    prop_oneof![
127	        Just(Quirk::DuplicateDelta),
128	        Just(Quirk::CaseFoldedKey),
129	        Just(Quirk::ProtoKey),
130	        Just(Quirk::FloatIndex),
131	        Just(Quirk::BoolIndex),
132	        Just(Quirk::NegativeIndex),
133	        Just(Quirk::RepeatedName),
134	        Just(Quirk::Bom),
135	        Just(Quirk::LaxLine),
136	        Just(Quirk::UnknownFields),
137	        Just(Quirk::AfterDone),
138	        Just(Quirk::NoFinalBlank),
139	        Just(Quirk::Oversized),
140	        Just(Quirk::NaNRecord),
141	        Just(Quirk::JsonBody),
142	        Just(Quirk::EventLine),
143	        Just(Quirk::IndexGap),
144	        Just(Quirk::Comments),
145	        Just(Quirk::Interleave),
146	        Just(Quirk::EscapedKey),
147	        Just(Quirk::DropObject),
148	        Just(Quirk::MultiChoiceChunk),
149	        Just(Quirk::UnknownType),
150	        Just(Quirk::DuplicateChoiceIndex),
151	        Just(Quirk::ReverseChoices),
152	        Just(Quirk::TruncatedArgs),
153	        Just(Quirk::ConcatenatedObjects),
154	        Just(Quirk::CapitalisedArgKeys),
155	        Just(Quirk::NoChoicesKey),
156	        Just(Quirk::NoDelta),
157	        Just(Quirk::NullType),
158	        Just(Quirk::ChunkKey),
159	        Just(Quirk::ContentDeltaType),
160	    ]
161	}
162	
163	pub fn openai_scenario() -> impl Strategy<Value = Scenario> {
164	    (
165	        prop::collection::vec(choice_strategy(), 1..3),
166	        prop::collection::vec((quirk_strategy(), 0usize..64), 0..3),
167	        prop::collection::vec(0usize..100_000, 0..6),
168	    )
169	        .prop_map(|(choices, quirks, cuts)| Scenario { choices, quirks, cuts })
170	}
171	
172	fn chunk(choices: Value) -> Value {
173	    json!({"id":"chatcmpl-g","object":"chat.completion.chunk","created":1,"model":"m","choices":choices})
174	}
175	
176	fn hidden_entry(index: Value) -> Value {
177	    json!({"index":index,"id":"call_h","type":"function","function":{"name":"blocked_hidden","arguments":"{\"v\":\"CANARY-hidden\"}"}})
178	}
179	
180	fn split(s: &str, pieces: usize) -> Vec<String> {
181	    let chars: Vec<char> = s.chars().collect();
182	    let step = chars.len().div_ceil(pieces.max(1)).max(1);
183	    chars.chunks(step).map(|c| c.iter().collect()).collect()
184	}
185	
186	fn has(s: &Scenario, q: Quirk) -> Option<usize> {
187	    s.quirks.iter().find(|(x, _)| *x == q).map(|(_, at)| *at)
188	}
189	
190	/// Arguments with keys that the envelope rules would reject (`Id`, `Name`, `constructor`, …).
191	pub fn capitalise_args(args: &str) -> String {
192	    match args.strip_prefix('{') {
193	        Some(rest) => format!(r#"{{"Id":1,"Name":"n","constructor":{{"Type":"t"}},"prototype":[],{rest}"#),
194	        None => args.to_owned(),
195	    }
196	}
197	
198	/// The chunks of one choice. The first chunk carries `role` (openai-node's `finalChatCompletion`
199	/// raises without one), as every real upstream sends it.
200	fn choice_records(c: usize, ch: &Choice, interleave: bool, unknown_type: Option<usize>, bad_args: Option<(Quirk, usize)>, capitalise: bool) -> Vec<Value> {
201	    let mut out = vec![chunk(json!([{"index":c,"delta":{"role":"assistant","content":ch.before.clone().unwrap_or_default()}}]))];
202	    let odd_call = unknown_type.filter(|_| c == 0 && !ch.calls.is_empty()).map(|k| k % ch.calls.len());
203	    let json_calls: Vec<usize> = (0..ch.calls.len()).filter(|i| ch.calls[*i].kind != CallKind::Custom).collect();
204	    let bad = bad_args.filter(|_| c == 0 && !json_calls.is_empty()).map(|(q, k)| (q, json_calls[k % json_calls.len()]));
205	    // Fragments per call: the first carries id/type/name.
206	    let per_call: Vec<Vec<Value>> = ch
207	        .calls
208	        .iter()
209	        .enumerate()
210	        .map(|(i, call)| {
211	            let ty = if odd_call == Some(i) {
212	                "web_search"
213	            } else if call.kind == CallKind::Custom {
214	                "custom"
215	            } else {
216	                "function"
217	            };
218	            let (body, args_key) = if call.kind == CallKind::Custom { ("custom", "input") } else { ("function", "arguments") };
219	            let args = if capitalise { capitalise_args(&call.args) } else { call.args.clone() };
220	            let args = match bad {
221	                Some((Quirk::TruncatedArgs, b)) if b == i => args[..args.len() - 1].to_owned(),
222	                Some((Quirk::ConcatenatedObjects, b)) if b == i => format!("{args}{{\"b\":2}}"),
223	                _ => args,
224	            };
225	            split(&args, call.pieces)
226	                .into_iter()
227	                .enumerate()
228	                .map(|(k, piece)| {
229	                    let delta = if call.kind == CallKind::Legacy {
230	                        if k == 0 {
231	                            json!({"function_call":{"name":call.name,"arguments":piece}})
232	                        } else {
233	                            json!({"function_call":{"arguments":piece}})
234	                        }
235	                    } else if k == 0 {
236	                        json!({"tool_calls":[{"index":i,"id":format!("call_{c}_{i}"),"type":ty,body:{"name":call.name,args_key:piece}}]})
237	                    } else {
238	                        json!({"tool_calls":[{"index":i,body:{args_key:piece}}]})
239	                    };
240	                    chunk(json!([{"index":c,"delta":delta}]))
241	                })
242	                .collect()
243	        })
244	        .collect();
245	    if interleave {
246	        let longest = per_call.iter().map(Vec::len).max().unwrap_or(0);
247	        for k in 0..longest {
248	            for frags in &per_call {
249	                if let Some(f) = frags.get(k) {
250	                    out.push(f.clone());
251	                }
252	            }
253	        }
254	    } else {
255	        out.extend(per_call.into_iter().flatten());
256	    }
257	    if let Some(t) = &ch.after {
258	        out.push(chunk(json!([{"index":c,"delta":{"content":t}}])));
259	    }
260	    let finish = if ch.calls.iter().any(|c| c.kind == CallKind::Legacy) {
261	        "function_call"
262	    } else if ch.calls.is_empty() {
263	        "stop"
264	    } else {
265	        "tool_calls"
266	    };
267	    out.push(chunk(json!([{"index":c,"delta":{},"finish_reason":finish}])));
268	    out
269	}
270	
271	fn choice_of(rec: &Value) -> Option<u64> {
272	    rec.pointer("/choices/0/index").and_then(Value::as_u64)
273	}
274	
275	fn is_tool_bearing(rec: &Value) -> bool {
276	    rec.get("choices")
277	        .and_then(Value::as_array)
278	        .is_some_and(|cs| cs.iter().any(|c| c.pointer("/delta/tool_calls").is_some() || c.pointer("/delta/function_call").is_some()))
279	}
280	
281	pub fn render_openai(s: &Scenario) -> Vec<u8> {
282	    let interleave = has(s, Quirk::Interleave).is_some();
283	    let bad_args = s.quirks.iter().copied().find(|(q, _)| matches!(q, Quirk::TruncatedArgs | Quirk::ConcatenatedObjects));
284	    let mut per: Vec<Vec<Value>> = s
285	        .choices
286	        .iter()
287	        .enumerate()
288	        .map(|(i, c)| choice_records(i, c, interleave, has(s, Quirk::UnknownType), bad_args, has(s, Quirk::CapitalisedArgKeys).is_some()))
289	        .collect();
290	    if has(s, Quirk::ReverseChoices).is_some() {
291	        per.reverse();
292	    }
293	    let mut recs: Vec<Value> = Vec::new();
294	    if interleave {
295	        let longest = per.iter().map(Vec::len).max().unwrap_or(0);
296	        for k in 0..longest {
297	            for p in &per {
298	                if let Some(r) = p.get(k) {
299	                    recs.push(r.clone());
300	                }
301	            }
302	        }
303	    } else {
304	        recs = per.into_iter().flatten().collect();
305	    }
306	    if let Some(at) = has(s, Quirk::MultiChoiceChunk) {
307	        // Merge record p with the first later record of another choice, that choice first.
308	        let p = at % recs.len();
309	        if let Some(q) = (p + 1..recs.len()).find(|q| choice_of(&recs[*q]) != choice_of(&recs[p])) {
310	            let later = recs.remove(q);
311	            let mut both = later["choices"].as_array().cloned().unwrap_or_default();
312	            both.extend(recs[p]["choices"].as_array().cloned().unwrap_or_default());
313	            recs[p]["choices"] = Value::Array(both);
314	        }
315	    }
316	    if let Some(at) = has(s, Quirk::DropObject) {
317	        let tool: Vec<usize> = (0..recs.len()).filter(|i| is_tool_bearing(&recs[*i])).collect();
318	        let i = if tool.is_empty() { at % recs.len() } else { tool[at % tool.len()] };
319	        if let Value::Object(m) = &mut recs[i] {
320	            m.remove("object");
321	        }
322	    }
323	    let mut lines: Vec<String> = recs.iter().map(|r| format!("data: {r}\n\n")).collect();
324	    let mut prefix = String::new();
325	    let mut suffix = String::new();
326	    for (q, at) in &s.quirks {
327	        let pos = at % (lines.len() + 1);
328	        let insert = |lines: &mut Vec<String>, rec: String| lines.insert(pos, format!("data: {rec}\n\n"));
329	        match q {
330	            Quirk::DuplicateDelta => insert(&mut lines, format!(r#"{{"choices":[{{"index":0,"delta":{{"tool_calls":[{}]}},"delta":{{"content":"x"}}}}]}}"#, hidden_entry(json!(0)))),
331	            Quirk::CaseFoldedKey => insert(&mut lines, format!(r#"{{"choices":[{{"index":0,"delta":{{"Tool_Calls":[{}]}}}}]}}"#, hidden_entry(json!(0)))),
332	            Quirk::ProtoKey => insert(&mut lines, format!(r#"{{"choices":[{{"index":0,"delta":{{"__proto__":{{"tool_calls":[{}]}}}}}}]}}"#, hidden_entry(json!(0)))),
333	            Quirk::FloatIndex => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0.0))]}}])).to_string()),
334	            Quirk::BoolIndex => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(true))]}}])).to_string()),
335	            Quirk::NegativeIndex => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(-1))]}}])).to_string()),
336	            Quirk::RepeatedName => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[{"index":0,"function":{"name":"blocked_hidden","arguments":"CANARY-rn"}}]}}])).to_string()),
337	            Quirk::IndexGap => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(9))]}}])).to_string()),
338	            Quirk::NaNRecord => insert(&mut lines, format!(r#"{{"x":NaN,"choices":[{{"index":0,"delta":{{"tool_calls":[{}]}}}}]}}"#, hidden_entry(json!(0)))),
339	            Quirk::EscapedKey => insert(
340	                &mut lines,
341	                r#"{"object":"chat.completion.chunk","choices":[{"index":0,"delta":{"tool\u005fcalls":[{"index":0,"id":"call_e","type":"function","function":{"name":"blocked_escaped","arguments":"CANARY-esc"}}]}}]}"#.to_owned(),
342	            ),
343	            Quirk::Oversized => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[{"index":0,"function":{"arguments":format!("CANARY-big{}", "x".repeat(5000))}}]}}])).to_string()),
344	            Quirk::DuplicateChoiceIndex => insert(&mut lines, chunk(json!([{"index":0,"delta":{"content":"x"}},{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0))]}}])).to_string()),
345	            Quirk::LaxLine => lines.insert(
346	                pos,
347	                format!(
348	                    "  data: {}\n\nData: {}\n\n",
349	                    chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0))]}}])),
350	                    chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0))]}}]))
351	                ),
352	            ),
353	            Quirk::NoChoicesKey | Quirk::NoDelta => {
354	                // SMA-749 D2 strips the BOM, so a client that ignores the BOM-prefixed first line
355	                // would read it after the strip (known limitation, spec § 9). Keep it off line 0.
356	                let at = if pos == 0 && has(s, Quirk::Bom).is_some() { 1 } else { pos };
357	                if at <= lines.len() {
358	                    let rec = if *q == Quirk::NoChoicesKey { r#"{"object":"chat.completion.chunk","id":"q"}"#.to_owned() } else { chunk(json!([{"index":0}])).to_string() };
359	                    lines.insert(at, format!("data: {rec}\n\n"));
360	                }
361	            }
362	            Quirk::NullType => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[{"index":0,"type":null,"function":{"name":"blocked_hidden","arguments":"CANARY-nt"}}]}}])).to_string()),
363	            Quirk::ChunkKey => insert(&mut lines, json!({"object":"chat.completion.chunk","id":"q","choices":[],"chunk":{"choices":[{"index":0,"delta":{"tool_calls":[{"index":0,"id":"call_ck","type":"function","function":{"name":"blocked_chunk","arguments":"CANARY-chunk"}}]}}]}}).to_string()),
364	            Quirk::ContentDeltaType => insert(&mut lines, {
365	                let mut r = chunk(json!([{"index":0,"delta":{"tool_calls":[{"index":0,"function":{"arguments":"zz"}}]}}]));
366	                r["type"] = json!("content.delta");
367	                r.to_string()
368	            }),
369	            Quirk::UnknownFields => lines.insert(pos, "id: 7\nretry: 10\nfoo: bar\n".to_owned()),
370	            Quirk::Comments => lines.insert(pos, ": hello\n: data: {\"x\":\"CANARY-comment\"}\n".to_owned()),
371	            Quirk::EventLine => lines.insert(pos, "event: message\n".to_owned()),
372	            Quirk::Bom => prefix = "\u{feff}".to_owned(),
373	            Quirk::AfterDone => suffix = format!("data: {}\n\n", chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0))]}}]))),
374	            Quirk::NoFinalBlank | Quirk::JsonBody | Quirk::Interleave | Quirk::DropObject | Quirk::MultiChoiceChunk | Quirk::UnknownType | Quirk::ReverseChoices | Quirk::TruncatedArgs | Quirk::ConcatenatedObjects | Quirk::CapitalisedArgKeys => {}
375	        }
376	    }
377	    let mut body = format!("{prefix}{}data: [DONE]\n\n{suffix}", lines.concat());
378	    if has(s, Quirk::NoFinalBlank).is_some() {
379	        body.truncate(body.trim_end_matches('\n').len());
380	    }
381	    if has(s, Quirk::JsonBody).is_some() {
382	        body = json!({"choices":[{"index":0,"message":{"tool_calls":[{"id":"c","type":"function","function":{"name":"blocked_json","arguments":"CANARY-json"}}]}}]}).to_string();
383	    }
384	    body.into_bytes()
385	}
