401	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
402	pub enum AQuirk {
403	    EventMismatch,
404	    PrefilledInput,
405	    PrefilledMessage,
406	    IndexReuse,
407	    NoEventLines,
408	    Bom,
409	    AfterStop,
410	    DuplicateKey,
411	    Oversized,
412	    /// The next block starts before the previous one stops (`block_interleave`).
413	    Interleave,
414	    /// A tool's last argument piece is lost, so its JSON is incomplete (`incomplete_arguments`).
415	    TruncatedArgs,
416	    /// A delta with index -1 (anthropic-python's `content[-1]` is the last block).
417	    NegativeIndex,
418	    /// A delta for a block after its stop.
419	    DeltaAfterStop,
420	    /// Every tool's input gains PascalCase, `constructor` and `prototype` keys (application data,
421	    /// so conforming; I-1).
422	    CapitalisedArgKeys,
423	}
424	
425	pub fn anthropic_scenario() -> impl Strategy<Value = AnthropicScenario> {
426	    let block = prop_oneof![
427	        "[a-z ]{1,10}".prop_map(Block::Text),
428	        (prop::bool::ANY, 0usize..2, "[a-z]{0,10}", 1usize..4).prop_map(|(b, n, s, pieces)| if b {
429	            Block::Tool {
430	                name: BLOCKED[n],
431	                args: format!("{{\"v\":\"CANARY-{s}\",\"n\":10.5}}"),
432	                pieces,
433	            }
434	        } else {
435	            Block::Tool {
436	                name: ALLOWED[n],
437	                args: format!("{{\"v\":\"{s}\",\"n\":10.5}}"),
438	                pieces,
439	            }
440	        }),
441	        Just(Block::Server),
442	    ];
443	    let quirk = prop_oneof![
444	        Just(AQuirk::EventMismatch),
445	        Just(AQuirk::PrefilledInput),
446	        Just(AQuirk::PrefilledMessage),
447	        Just(AQuirk::IndexReuse),
448	        Just(AQuirk::NoEventLines),
449	        Just(AQuirk::Bom),
450	        Just(AQuirk::AfterStop),
451	        Just(AQuirk::DuplicateKey),
452	        Just(AQuirk::Oversized),
453	        Just(AQuirk::Interleave),
454	        Just(AQuirk::TruncatedArgs),
455	        Just(AQuirk::NegativeIndex),
456	        Just(AQuirk::DeltaAfterStop),
457	        Just(AQuirk::CapitalisedArgKeys),
458	    ];
459	    (
460	        prop::collection::vec(block, 0..5),
461	        prop::collection::vec((quirk, 0usize..64), 0..3),
462	        prop::collection::vec(0usize..100_000, 0..6),
463	    )
464	        .prop_map(|(blocks, quirks, cuts)| AnthropicScenario { blocks, quirks, cuts })
465	}
