471	pub fn render_anthropic(s: &AnthropicScenario) -> Vec<u8> {
472	    let mut evs: Vec<Value> = vec![json!({"type":"message_start","message":{"id":"msg_g","type":"message","role":"assistant","content":[],"model":"c","usage":{"input_tokens":1,"output_tokens":1}}})];
473	    let tools: Vec<usize> = s.blocks.iter().enumerate().filter(|(_, b)| matches!(b, Block::Tool { .. })).map(|(i, _)| i).collect();
474	    let truncated = ahas(s, AQuirk::TruncatedArgs).filter(|_| !tools.is_empty()).map(|k| tools[k % tools.len()]);
475	    // With Interleave, block k's stop is deferred until after block k+1's start.
476	    let interleave_at = ahas(s, AQuirk::Interleave).filter(|_| s.blocks.len() > 1).map(|k| k % (s.blocks.len() - 1));
477	    let mut deferred: Option<Value> = None;
478	    for (i, b) in s.blocks.iter().enumerate() {
479	        match b {
480	            Block::Text(t) => {
481	                evs.push(json!({"type":"content_block_start","index":i,"content_block":{"type":"text","text":""}}));
482	                if let Some(d) = deferred.take() {
483	                    evs.push(d);
484	                }
485	                evs.push(json!({"type":"content_block_delta","index":i,"delta":{"type":"text_delta","text":t}}));
486	            }
487	            Block::Tool { name, args, pieces } => {
488	                evs.push(json!({"type":"content_block_start","index":i,"content_block":{"type":"tool_use","id":format!("toolu_{i}"),"name":name,"input":{}}}));
489	                if let Some(d) = deferred.take() {
490	                    evs.push(d);
491	                }
492	                let args = if ahas(s, AQuirk::CapitalisedArgKeys).is_some() { capitalise_args(args) } else { args.clone() };
493	                let mut parts = split(&args, *pieces);
494	                if truncated == Some(i) {
495	                    let last = parts.pop().unwrap_or_default();
496	                    parts.push(last[..last.len().saturating_sub(1)].to_owned());
497	                }
498	                for p in parts {
499	                    evs.push(json!({"type":"content_block_delta","index":i,"delta":{"type":"input_json_delta","partial_json":p}}));
500	                }
501	            }
502	            Block::Server => {
503	                evs.push(json!({"type":"content_block_start","index":i,"content_block":{"type":"server_tool_use","id":format!("srv_{i}"),"name":"web_search","input":{}}}));
504	                if let Some(d) = deferred.take() {
505	                    evs.push(d);
506	                }
507	                evs.push(json!({"type":"content_block_delta","index":i,"delta":{"type":"input_json_delta","partial_json":"{\"q\":\"x\"}"}}));
508	            }
509	        }
510	        let stop = json!({"type":"content_block_stop","index":i});
511	        if interleave_at == Some(i) {
512	            deferred = Some(stop);
513	        } else {
514	            evs.push(stop);
515	        }
516	    }
517	    let any_tool = !tools.is_empty();
518	    evs.push(json!({"type":"message_delta","delta":{"stop_reason": if any_tool { "tool_use" } else { "end_turn" },"stop_sequence":null},"usage":{"output_tokens":1}}));
519	    evs.push(json!({"type":"message_stop"}));
520	    let no_events = ahas(s, AQuirk::NoEventLines).is_some();
521	    let mut frames: Vec<String> = evs
522	        .iter()
523	        .map(|e| {
524	            if no_events {
525	                format!("data: {e}\n\n")
526	            } else {
527	                format!("event: {}\ndata: {e}\n\n", e["type"].as_str().unwrap())
528	            }
529	        })
530	        .collect();
531	    let hidden_start = |idx: usize, input: Value| json!({"type":"content_block_start","index":idx,"content_block":{"type":"tool_use","id":"toolu_h","name":"blocked_hidden","input":input}});
532	    let mut prefix = String::new();
533	    let mut suffix = String::new();
534	    for (q, at) in &s.quirks {
535	        let pos = 1 + at % frames.len().max(1);
536	        let pos = pos.min(frames.len().saturating_sub(1));
537	        match q {
538	            AQuirk::EventMismatch => frames.insert(pos, format!("event: ping\ndata: {}\n\n", hidden_start(s.blocks.len(), json!({"v":"CANARY-em"})))),
539	            AQuirk::PrefilledInput => frames.insert(pos, format!("event: content_block_start\ndata: {}\n\n", hidden_start(s.blocks.len(), json!({"v":"CANARY-pi"})))),
540	            AQuirk::PrefilledMessage => {
541	                frames[0] = format!(
542	                    "event: message_start\ndata: {}\n\n",
543	                    json!({"type":"message_start","message":{"content":[{"type":"tool_use","id":"t","name":"blocked_hidden","input":{"v":"CANARY-pm"}}]}})
544	                )
545	            }
546	            AQuirk::IndexReuse => frames.insert(
547	                pos,
548	                format!(
549	                    "event: content_block_start\ndata: {}\n\n",
550	                    json!({"type":"content_block_start","index":0,"content_block":{"type":"tool_use","id":"toolu_r","name":"blocked_reuse","input":{}}})
551	                ),
552	            ),
553	            AQuirk::DuplicateKey => frames.insert(
554	                pos,
555	                format!(
556	                    "event: content_block_delta\ndata: {}\n\n",
557	                    r#"{"type":"content_block_delta","index":0,"delta":{"type":"input_json_delta","partial_json":"CANARY-dup"},"delta":{"type":"text_delta","text":"x"}}"#
558	                ),
559	            ),
560	            AQuirk::Oversized => frames.insert(
561	                pos,
562	                format!(
563	                    "event: content_block_delta\ndata: {}\n\n",
564	                    json!({"type":"content_block_delta","index":0,"delta":{"type":"input_json_delta","partial_json":format!("CANARY-big{}", "x".repeat(5000))}})
565	                ),
566	            ),
567	            AQuirk::NegativeIndex => frames.insert(
568	                pos,
569	                format!(
570	                    "event: content_block_delta\ndata: {}\n\n",
571	                    json!({"type":"content_block_delta","index":-1,"delta":{"type":"input_json_delta","partial_json":"\"CANARY-neg\""}})
572	                ),
573	            ),
574	            AQuirk::DeltaAfterStop => frames.insert(
575	                frames.len().saturating_sub(2).max(1),
576	                format!(
577	                    "event: content_block_delta\ndata: {}\n\n",
578	                    json!({"type":"content_block_delta","index":0,"delta":{"type":"input_json_delta","partial_json":"\"CANARY-late\""}})
579	                ),
580	            ),
581	            AQuirk::Bom => prefix = "\u{feff}".to_owned(),
582	            AQuirk::AfterStop => suffix = format!("event: content_block_start\ndata: {}\n\n", hidden_start(s.blocks.len(), json!({}))),
583	            AQuirk::NoEventLines | AQuirk::Interleave | AQuirk::TruncatedArgs | AQuirk::CapitalisedArgKeys => {}
584	        }
585	    }
586	    format!("{prefix}{}{suffix}", frames.concat()).into_bytes()
587	}
