// SPDX-License-Identifier: Apache-2.0
mod support;
use paigasus_gateway_core::{Format, OnFailure};
use support::driver::{DECIDERS, drive, limits};
use support::oracle::{check_i1, runners};

fn rec(choices: &str) -> String {
    format!("data: {{\"id\":\"x\",\"object\":\"chat.completion.chunk\",\"choices\":{choices}}}\n\n")
}

fn probe(name: &str, recs: &[String]) {
    let body = format!("{}data: [DONE]\n\n", recs.concat());
    let b = body.as_bytes();
    for (m, r) in runners(Format::OpenAiChat) {
        let run = r(b);
        println!("{name} upstream {m}: err={:?} calls={:?}", run.error, run.calls);
    }
    for (dn, d) in DECIDERS {
        for of in [OnFailure::Block, OnFailure::Allow] {
            let o = drive(Format::OpenAiChat, limits(of), &[b], d);
            let r = check_i1(Format::OpenAiChat, b, &o.out, &o.decided, o.core_failed());
            println!("{name} {dn} {of:?} core_failed={} -> {:?}", o.core_failed(), r.as_ref().err().map(|e| e.lines().next().unwrap_or("").to_owned()));
        }
    }
}

#[test]
fn probes() {
    let f0 = rec(r#"[{"index":0,"delta":{"role":"assistant","tool_calls":[{"index":0,"id":"c0","type":"function","function":{"name":"read_file","arguments":"{\"v\":\"ab"}}]}}]"#);
    let f1 = rec(r#"[{"index":0,"delta":{"tool_calls":[{"index":0,"function":{"arguments":"cdefgh\"}"}}]}}]"#);
    let fin = rec(r#"[{"index":0,"delta":{},"finish_reason":"tool_calls"}]"#);
    // G1: an unknown delta key holding an indexed list, then a scalar list: openai-python accumulate_delta raises.
    let g1a = rec(r#"[{"index":0,"delta":{"foo":[{"index":0}]}}]"#);
    let g1b = rec(r#"[{"index":0,"delta":{"foo":[1]}}]"#);
    probe("G1", &[f0.clone(), g1a, g1b, f1.clone(), fin.clone()]);
    // G1b: the same inside the tool-call entry.
    let g1c = rec(r#"[{"index":0,"delta":{"tool_calls":[{"index":0,"function":{"arguments":""},"x":[{"index":0}]}]}}]"#);
    let g1d = rec(r#"[{"index":0,"delta":{"tool_calls":[{"index":0,"function":{"arguments":""},"x":[1]}]}}]"#);
    probe("G1b", &[f0.clone(), g1c, g1d, f1.clone(), fin.clone()]);
    // G2: legacy function_call with an extra key that changes type in a middle fragment.
    let l0 = rec(r#"[{"index":0,"delta":{"role":"assistant","function_call":{"name":"read_file","arguments":"{\"v\":\"ab","x":"s"}}}]"#);
    let l1 = rec(r#"[{"index":0,"delta":{"function_call":{"arguments":"cd","x":1}}}]"#);
    let l2 = rec(r#"[{"index":0,"delta":{"function_call":{"arguments":"efgh\"}"}}}]"#);
    let lfin = rec(r#"[{"index":0,"delta":{},"finish_reason":"function_call"}]"#);
    probe("G2", &[l0, l1, l2, lfin]);
    // G3: first fragment in the same record as a delta-less choice 1.
    let g3 = rec(r#"[{"index":0,"delta":{"role":"assistant","tool_calls":[{"index":0,"id":"c0","type":"function","function":{"name":"read_file","arguments":"{\"v\":\"ab"}}]}},{"index":1}]"#);
    probe("G3", &[g3, f1.clone(), fin.clone(), rec(r#"[{"index":1,"delta":{"role":"assistant","content":"x"},"finish_reason":"stop"}]"#)]);
    let pre = rec(r#"[{"index":0,"delta":{"role":"assistant","content":""}}]"#);
    let g3b = rec(r#"[{"index":0,"delta":{"tool_calls":[{"index":0,"id":"c0","type":"function","function":{"name":"read_file","arguments":"{\"v\":\"ab"}}]}},{"index":1}]"#);
    probe("G3b", &[pre.clone(), g3b, f1.clone(), fin.clone(), rec(r#"[{"index":1,"delta":{"role":"assistant","content":"x"},"finish_reason":"stop"}]"#)]);
    let pre2 = rec(r#"[{"index":0,"delta":{"role":"assistant","content":"","foo":[{"index":0}]}}]"#);
    let g1e = rec(r#"[{"index":0,"delta":{"tool_calls":[{"index":0,"id":"c0","type":"function","function":{"name":"read_file","arguments":"{\"v\":\"ab"}}],"foo":[1]}}]"#);
    probe("G1e", &[pre2, g1e, f1.clone(), fin.clone()]);
    // G4: openai-python list delta for 'content' type? a delta whose 'tool_calls' entry is fine but a sibling key 'refusal' list.
}

#[test]
fn body_null_type() {
    for t in ["null", "\"function\""] {
        let b = format!(r#"{{"object":"chat.completion","choices":[{{"index":0,"message":{{"role":"assistant","tool_calls":[{{"id":"c0","type":{t},"function":{{"name":"read","arguments":"{{}}"}}}}]}}}}]}}"#);
        println!("BODY type={t}: {:?}", paigasus_gateway_core::parse_body(Format::OpenAiChat, b.as_bytes(), 1 << 20).map(|c| c.calls.len()));
    }
}

#[test]
fn bare_null_type() {
    let r0 = rec(r#"[{"index":0,"delta":{"role":"assistant","tool_calls":[{"index":0,"id":"x","type":null}]}}]"#);
    let fin = rec(r#"[{"index":0,"delta":{},"finish_reason":"tool_calls"}]"#);
    probe("NULLTYPE", &[r0, fin]);
    let r1 = rec(r#"[{"index":0,"delta":{"role":"assistant","tool_calls":[{"index":0,"id":"x"}]}}]"#);
    let fin = rec(r#"[{"index":0,"delta":{},"finish_reason":"tool_calls"}]"#);
    probe("NOTYPE", &[r1, fin]);
}

