224	/// The split points to test for `bytes`. Every point costs three client runs (two processes
225	/// each), and a full sweep of the 12 recordings took over 100 s in a debug build. So a file up to
226	/// 4 KiB gets every point. A larger file gets a stride of 7 plus every record boundary (each
227	/// `\n\n` offset, and the offsets on both sides of it), where a split is most likely to matter.
228	fn split_points(bytes: &[u8]) -> Vec<usize> {
229	    if bytes.len() <= 4096 {
230	        return (0..=bytes.len()).collect();
231	    }
232	    let mut v: Vec<usize> = (0..=bytes.len()).step_by(7).collect();
233	    for (i, w) in bytes.windows(2).enumerate() {
234	        if w == b"\n\n" {
235	            v.extend([i, i + 1, i + 2]);
236	        }
237	    }
238	    v.push(bytes.len());
239	    v.sort_unstable();
240	    v.dedup();
241	    v.retain(|&i| i <= bytes.len());
242	    v
243	}
