245	/// Real OpenAI recordings (2026-11-14) pass the interceptor unchanged: no record is dropped, no
246	/// `on_failure` path runs, and every client derives the decided calls from the output.
247	#[test]
248	fn recorded_streams_pass_unchanged() {
249	    for (name, bytes) in files("openai/recorded") {
250	        for i in split_points(&bytes) {
251	            let o = drive(Format::OpenAiChat, limits(OnFailure::Block), &cut(&bytes, &[i]), &allow_all);
252	            let ctx = format!("recorded/{name} split at {i}");
253	            assert!(o.finished, "{ctx} never ended");
254	            assert!(!o.metrics.iter().any(|m| matches!(m, Metric::RecordDropped(_) | Metric::OnFailure(_))), "{ctx}: {:?}", o.metrics);
255	            check_i1(Format::OpenAiChat, &bytes, &o.out, &o.decided, o.core_failed()).unwrap_or_else(|e| panic!("{ctx}: {e}"));
256	            let want: Vec<(&str, String)> = o.decided.iter().map(|(c, _)| as_model_call(c)).map(|m| (m.kind, m.name)).collect();
257	            assert!(!want.is_empty(), "{ctx}: no tool call was decided");
258	            for (model, run) in runners(Format::OpenAiChat) {
259	                let r = run(&o.out);
260	                if let Some(e) = &r.error {
261	                    // Only LangChain on a recording with a `custom` call may raise: its model
262	                    // raises on any custom entry (oracle.rs), also on the recorded bytes.
263	                    let excused = *model == "langchain" && want.iter().any(|(k, _)| *k == "custom") && run(&bytes).error.is_some();
264	                    assert!(excused, "{ctx}: {model} raised: {e}");
265	                    continue;
266	                }
267	                let got: Vec<(&str, String)> = r.calls.iter().map(|m| (m.kind, m.name.clone())).collect();
268	                assert_eq!(got, want, "{ctx}: {model}");
269	            }
270	        }
271	    }
272	}
