411	/// openai-python `accumulate_delta`. `index` and `type` are replaced, strings and numbers added,
412	/// dicts merged, indexed lists merged by `list[index]` (Python indexing, `insert` on IndexError).
413	/// A value of a different type is kept, not replaced.
414	/// SOURCE: openai-python 3.40.0, src/openai/lib/streaming/_deltas.py accumulate_delta.
415	fn accumulate_delta(acc: &mut Map<String, Value>, delta: &Map<String, Value>) -> Result<(), String> {
416	    for (k, dv) in delta {
417	        if acc.get(k).is_none_or(Value::is_null) {
418	            if has_indexed_entries(dv) {
419	                acc.insert(k.clone(), Value::Array(Vec::new()));
420	            } else {
421	                acc.insert(k.clone(), dv.clone());
422	                continue;
423	            }
424	        }
425	        if k == "index" || k == "type" {
426	            acc.insert(k.clone(), dv.clone());
427	            continue;
428	        }
429	        let av = acc.get_mut(k).expect("present");
430	        if let Some(sum) = py_add_numbers(av, dv) {
431	            *av = sum;
432	            continue;
433	        }
434	        match (av, dv) {
435	            (Value::String(a), Value::String(b)) => a.push_str(b),
436	            (Value::Object(a), Value::Object(b)) => accumulate_delta(a, b)?,
437	            (Value::Array(a), Value::Array(b)) => {
438	                if a.iter().all(py_scalar) && (!a.is_empty() || !has_indexed_entries(dv)) {
439	                    a.extend(b.iter().cloned());
440	                    continue;
441	                }
442	                for e in b {
443	                    let Value::Object(eo) = e else {
444	                        return Err("TypeError: list delta entry is not a dictionary".into());
445	                    };
446	                    let idx = eo.get("index").ok_or("RuntimeError: list delta entry without `index`")?;
447	                    let idx = py_int(idx).ok_or("TypeError: list delta entry `index` is not an integer")?;
448	                    match py_get(a.len(), idx) {
449	                        Some(p) => {
450	                            let Value::Object(target) = &mut a[p] else { return Err("TypeError: not handled yet".into()) };
451	                            accumulate_delta(target, eo)?;
452	                        }
453	                        None => a.insert(py_insert_at(a.len(), idx), e.clone()),
454	                    }
455	                }
456	            }
457	            _ => {} // different types: the accumulated value is kept
458	        }
459	    }
460	    Ok(())
461	}
